	["Cópialo con Ctrl+C y guárdalo, o pásaselo a la manada. Para traerlo de vuelta: «Importar»."] = "Copie com Ctrl+C e guarde, ou passe para a matilha. Para trazer de volta: «Importar».",
	["Cópialo con Ctrl+C. Luego abre «Hermandad y comunidades», elige %s, pulsa «Invitar a miembro» y pégalo con Ctrl+V."] = "Copie com Ctrl+C. Depois abra “Guilda e Comunidades”, escolha %s, clique em “Convidar membro” e cole com Ctrl+V.",
	["DPS"] = "DPS",
