	["Daga"] = "Adaga",
	["Dale de comer a tu mascota para que esté contenta y pegue más."] = "Alimente seu ajudante para ele ficar feliz e bater mais.",
	["Dale de comer para que esté feliz: pega más fuerte."] = "Alimente-o para ele ficar feliz: ele bate mais forte.",
	["Dame clic derecho y elige «¿En qué te ayudo?» cuando quieras. ¡Buena caza, lobo!"] = "Clique com o botão direito em mim e escolha «Em que te ajudo?» quando quiser. Boa caçada, lobo!",
