	["El paisaje lejano deja de perderse en la niebla espesa."] = "A paisagem distante deixa de sumir na neblina espessa.",
	["El paisaje lejano deja de perderse en la niebla espesa. A veces se nota dónde termina lo que está cargado."] = "A paisagem distante deixa de sumir na neblina espessa. Às vezes dá para ver onde termina o que está carregado.",
	["El paquete de datos de Alfa (Alfa_Codex) está desactivado: actívalo en la lista de addons y recarga."] = "O pacote de dados do Alfa (Alfa_Codex) está desativado: ative-o na lista de addons e recarregue.",
	["El paso de ahora de tu guía te lleva a entrenar."] = "O passo atual do seu guia leva você para treinar.",
	["El pequeño rey Anduin Wrynn lleva su nombre en honor a Anduin Lothar, el héroe que salvó a su pueblo."] = "O pequeno rei Anduin Wrynn leva esse nome em honra a Anduin Lothar, o herói que salvou seu povo.",
	["El primer clic abre la Cocina del juego; el siguiente cocina el lote. Tienes que estar junto a un fuego."] = "O primeiro clique abre a janela de Culinária do jogo; o seguinte cozinha o lote. Você precisa estar perto de um fogo.",
	["El primer jefe de guerra de la Horda fue Mano Negra. Su hijo Rend Mano Negra hoy sirve a Nefarian en la Cumbre de Roca Negra."] = "O primeiro chefe guerreiro da Horda foi Mão Negra. Seu filho Rend Mão Negra hoje serve a Nefarian no Pico da Rocha Negra.",
	["El primer punto del Legado suele llegar al nivel 25, y con él se abre el Legado."] = "O primeiro ponto do Legado costuma chegar no nível 25, e com ele o Legado é liberado.",
	["El próximo: %s"] = "O próximo: %s",
	["El pícaro más fácil para subir: pega de frente, esquiva mucho y aguanta mejor que los demás."] = "O ladino mais fácil para subir de nível: bate de frente, se esquiva muito e aguenta mais que os outros.",
	["El rango Experto viene en un libro que vende el pescador de Bahía del Botín, en Tuercespina."] = "A faixa Especialista vem num livro que o pescador de Angra do Butim vende, na Selva do Espinhaço.",
