	["En Burning Crusade, el Vuelo Bronce pide ayuda en las Cavernas del Tiempo contra dragones que quieren cambiar la historia."] = "Em Burning Crusade, a Revoada Bronze pede ajuda nas Cavernas do Tempo contra dragões que querem mudar a história.",
	["En Burning Crusade, las Cavernas del Tiempo te regresan a estas laderas para ver la huida de Thrall de Durnholde."] = "Em Burning Crusade, as Cavernas do Tempo levam você de volta a estas encostas para ver a fuga de Thrall de Durnholde.",
	["En Caer Darrow, junto al lago, todavía rondan los fantasmas de sus antiguos vecinos."] = "Em Caer Darrow, junto ao lago, ainda rondam os fantasmas dos antigos moradores.",
	["En Ciudad Manitas, dentro de Forjaz, viven los gnomos que escaparon de Gnomeregan."] = "No Beco da Gambiarra, dentro de Altaforja, vivem os gnomos que fugiram de Gnomeregan.",
	["En Combate tienes el medidor de daño del grupo y la ayuda de rotación para tu clase."] = "Em Combate você tem o medidor de dano do grupo e a ajuda de rotação da sua classe.",
	["En Comercio ves precios de la subasta y qué te conviene vender. Yo vendo lo gris por ti con el comerciante."] = "Em Comércio você vê preços do leilão e o que vale vender. Eu vendo o cinza por você no vendedor.",
	["En Costa Oscura la Liga de Expedicionarios desentierra fósiles gigantes."] = "Na Costa Negra, a Liga dos Exploradores desenterra fósseis gigantes.",
	["En Costa Oscura viven lechúcicos, criaturas mitad búho y mitad oso que veneran la luna."] = "Na Costa Negra vivem luniscantes, criaturas metade coruja e metade urso que veneram a lua.",
	["En Desolace está el cementerio de los kodos, donde los viejos kodos van a morir."] = "Em Desolação fica o Cemitério dos Kodos, aonde os kodos velhos vão morrer.",
	["En Durotar ya te topas con el Filo Ardiente, un culto de brujos orcos que sigue adorando a los demonios."] = "Em Durotar você já topa com a Lâmina Ardente, um culto de bruxos orcs que continua adorando os demônios.",
	["En Elwynn, una señora vende gatitos de compañía. ¡Yo me llevo bien con los gatos... casi siempre!"] = "Em Elwynn, uma senhora vende gatinhos de estimação. Eu me dou bem com gatos... quase sempre!",
	["En Entrañas venden cucarachas de mascota. Cada quien sus gustos."] = "Na Cidade Baixa vendem baratas como mascote. Gosto não se discute.",
	["En Feralas está uno de los grandes árboles por los que los dragones verdes entran al Sueño Esmeralda."] = "Em Feralas fica uma das grandes árvores pelas quais os dragões verdes entram no Sonho Esmeralda.",
	["En Forever, Onyxia, la Cumbre Hyjal y Barrow Deeps dan retos del Legado al vencerlas."] = "No Forever, Onyxia, o Cume Hyjal e Barrow Deeps dão desafios do Legado ao serem vencidos.",
	["En Forever, el banco vende casillas de bolsa una tras otra: más espacio para tus tesoros."] = "No Forever, o banco vende espaços de bolsa um atrás do outro: mais espaço para os seus tesouros.",
	["En Forever, los rangos de honor y la reputación de los campos de batalla también dan retos del Legado."] = "No Forever, as patentes de honra e a reputação dos campos de batalha também dão desafios do Legado.",
	["En Forever, los retos del Legado dan puntos a toda tu cuenta, y cada personaje los gasta en sus árboles. Ábrelo con la tecla Y."] = "No Forever, os desafios do Legado dão pontos para toda a sua conta, e cada personagem os gasta nas suas árvores. Abra com a tecla Y.",
	["En Forjaz, la sala de la Liga de Expedicionarios tiene un museo con fósiles enormes. Brann Barbabronce es su explorador más famoso."] = "Em Altaforja, o salão da Liga dos Exploradores tem um museu com fósseis enormes. Brann Barbabronze é seu explorador mais famoso.",
	["En Gadgetzan, el cocinero Dirge enseña una de las mejores recetas del Clásico, con carne de quimerok."] = "Em Gadgetzan, o cozinheiro Dirge ensina uma das melhores receitas do Clássico, com carne de quimerok.",
	["En Jaedenar se esconde el Consejo de la Sombra, brujos que sirven a la Legión Ardiente."] = "Em Jaedenar se esconde o Conselho das Sombras, bruxos que servem à Legião Ardente.",
	["En Jardín Noble se esconden huevos de colores por los pueblos iniciales; dentro hay dulces y a veces ropa de primavera."] = "No Jardinova, ovos coloridos ficam escondidos pelos povoados iniciais; dentro há doces e às vezes roupas de primavera.",
	["En Kharanos, la posada y la destilería Cebatruenos son la parada obligada para calentarse... por dentro y por fuera."] = "Em Kharanos, a estalagem e a Destilaria Cervatrovão são parada obrigatória para se esquentar... por dentro e por fora.",
	["En La Jauría > Guaridas te digo en cuál estás y en cuáles anda la manada. Con «Pedir entrar» te pasas a la de un lobo con la puerta abierta."] = "Em La Jauría > Tocas eu digo em qual você está e onde anda a matilha. Com “Pedir para entrar” você passa para a de um lobo com a porta aberta.",
	["En La Jauría > Guaridas toca «Llamar a la manada» (o escribe /alfa manada llamar): los lobos de tu zona reciben tu lugar y te aviso quién viene."] = "Em La Jauría > Tocas toque em “Chamar a matilha” (ou /alfa manada llamar): os lobos da sua zona recebem seu local e eu aviso quem vem.",
	["En La Jauría ves a tu grupo y a los lobos que se dejan ver en el mapa. Puedes seguirlos con la flecha o invitarlos."] = "Em La Jauría você vê seu grupo e os lobos que aparecem no mapa. Pode segui-los com a seta ou convidá-los.",
	["En La Jauría, en «Citas de la manada», escribe qué, elige día y hora y pulsa «Proponer». A tu hermandad le llega con «Voy» y yo te recuerdo 15 minutos antes."] = "Em La Jauría, em \"Encontros da matilha\", escreva o quê, escolha dia e hora e aperte \"Propor\". Sua guilda recebe com \"Eu vou\" e eu te lembro 15 minutos antes.",
	["En Mazmorras ves cuáles van con tu nivel, sus jefes, su botín, sus misiones y cómo llegar a la entrada."] = "Em Masmorras você vê as do seu nível, chefes, saque, missões e como chegar à entrada.",
	["En Molino Ámbar se refugian magos de Dalaran, y no les gustan nada las visitas de los Renegados."] = "No Moinho Âmbar se refugiam magos de Dalaran, e eles não gostam nada das visitas dos Renegados.",
	["En Mundo pones tus marcadores, los compartes con tu grupo y la flecha te lleva a ellos."] = "Em Mundo você coloca seus marcadores, compartilha com o grupo e a seta leva você até eles.",
	["En Naxxramas, el gran Alexandros Mograine reaparece como uno de los Cuatro Jinetes de la Plaga. Qué triste destino para un héroe."] = "Em Naxxramas, o grande Alexandros Mograine reaparece como um dos Quatro Cavaleiros do Flagelo. Que destino triste para um herói.",
	["En Nethergarde, unos magos de sangre te cambian partes de las bestias de aquí por elixires que te potencian un buen rato."] = "Em Nethergarde, uns magos de sangue trocam partes das feras daqui por elixires que fortalecem você por um bom tempo.",
	["En Orgrimmar, el Valle de la Sabiduría guarda la fortaleza de Thrall, y el Valle del Honor reúne a guerreros y cazadores."] = "Em Orgrimmar, o Vale da Sabedoria guarda a fortaleza de Thrall, e o Vale da Honra reúne guerreiros e caçadores.",
	["En Paisaje y gráficos hay un paisaje más bonito con un clic, y cada ajuste gráfico explicado."] = "Em Paisagem e gráficos há uma paisagem mais bonita com um clique, e cada ajuste gráfico explicado.",
	["En Pesca tienes una sola tecla para equiparte, lanzar y recoger, un diario de lo que sacas y una guía de 1 a 300."] = "Em Pesca você tem uma única tecla para se equipar, lançar e recolher, um diário do que pesca e um guia de 1 a 300.",
	["En Pico Nidal manda el thane Falstad Martillo Salvaje, señor de los jinetes de grifo."] = "No Ninho da Águia manda o thane Falstad Martelo Feroz, senhor dos cavaleiros de grifo.",
	["En Pico Nidal viven los enanos Martillo Salvaje, famosos por volar sobre grifos."] = "No Ninho da Águia vivem os anões Martelo Feroz, famosos por voar em grifos.",
	["En Recolección eliges qué buscar y te marco en el mapa los puntos de tus profesiones, con los que ya encontraste."] = "Em Coleta você escolhe o que procurar e eu marco no mapa os pontos das suas profissões, com os que você já achou.",
	["En Ruta eliges a dónde ir y yo te armo el camino. La flecha te lleva paso a paso y el rastrador te dice qué toca."] = "Em Rota você escolhe para onde ir e eu monto o caminho. A seta leva você passo a passo e o rastreador diz o que vem.",
	["En Seradane hay uno de los grandes árboles que llevan al Sueño Esmeralda, y los dragones verdes lo custodian."] = "Em Seradane fica uma das grandes árvores que levam ao Sonho Esmeralda, e os dragões verdes a guardam.",
	["En Talentos te digo qué punto poner y por qué, según tu clase y cómo juegas."] = "Em Talentos eu digo qual ponto colocar e por quê, conforme sua classe e seu jeito de jogar.",
	["En Tanaris están las Cavernas del Tiempo, donde el Vuelo Bronce de Nozdormu vigila la historia."] = "Em Tanaris ficam as Cavernas do Tempo, onde a Revoada Bronze de Nozdormu vigia a história.",
	["En Tirisfal está la entrada al Monasterio Escarlata, uno de los lugares más visitados por los aventureros de nivel medio."] = "Em Tirisfal fica a entrada do Monastério Escarlate, um dos lugares mais visitados pelos aventureiros de nível médio.",
	["En Uldaman están los Discos de Norgannon, registros de los titanes que cuentan cómo crearon a los terráneos, los antepasados de piedra de los enanos."] = "Em Uldaman estão os Discos de Norgannon, registros dos titãs que contam como criaram os terranos, os ancestrais de pedra dos anões.",
	["En Vallefresno, Grom Grito Infernal mató al semidiós Cenarius cuando la Horda empezó a talar el bosque."] = "No Vale Gris, Grom Grito Infernal matou o semideus Cenarius quando a Horda começou a derrubar a floresta.",
	["En Vallefresno, Grom volvió a beber sangre demoníaca; Thrall lo rescató y Grom pudo redimirse antes de morir."] = "No Vale Gris, Grom voltou a beber sangue demoníaco; Thrall o resgatou e Grom pôde se redimir antes de morrer.",
	["En Ventormenta hay un barrio de enanos, uno de magos y un parque donde se reúnen los elfos de la noche."] = "Em Ventobravo há um bairro de anões, um de magos e um parque onde os elfos noturnos se reúnem.",
	["En Warcraft III, si le das muchos clics a una unidad empieza a decir cosas chistosas. Yo, en cambio, te doy consejos."] = "No Warcraft III, se você clicar muitas vezes numa unidade, ela começa a dizer coisas engraçadas. Eu, por outro lado, dou dicas.",
	["En arco"] = "Em arco",
	["En bancos de peces de: %s."] = "Em cardumes de: %s.",
	["En camino"] = "A caminho",
	["En cero los números suben derechos; más alto, salen disparados hacia los lados."] = "Em zero os números sobem retos; mais alto, saem disparados para os lados.",
	["En combate"] = "Em combate",
	["En combate el juego oculta los números exactos: las barras y las cifras se ven igual, el detalle y el anuncio, al salir."] = "Em combate, o jogo esconde os números exatos: as barras e os valores aparecem normalmente; o detalhe e o anúncio, ao sair.",
	["En combate el mapa del juego no se abre desde Alfa: usa el de Alfa."] = "Em combate, o mapa do jogo não abre pelo Alfa: use o do Alfa.",
	["En combate no aparece el cuadro de los personajes y criaturas del mundo (el de los marcos sí)."] = "Em combate, a dica dos personagens e criaturas do mundo não aparece (a dos quadros, sim).",
	["En combate no hay prueba: sal de la pelea y vuelve a este paso."] = "Em combate não há teste: saia da luta e volte a este passo.",
	["En combate no puedo buscar: inténtalo al terminar la pelea."] = "Em combate não posso buscar: tente quando a luta acabar.",
	["En combate no se puede: espera a terminar."] = "Em combate não dá: espere terminar.",
	["En combate · la pesca espera"] = "Em combate · a pesca espera",
	["En combate, el ícono muestra la habilidad que sugiere la ayuda de Blizzard y las %d que siguen. Tú decides qué presionar: Alfa nunca aprieta nada por ti."] = "Em combate, o ícone mostra a habilidade que a ajuda de combate da Blizzard sugere e as %d seguintes. Você decide o que apertar: o Alfa nunca aperta nada por você.",
	["En combate, el ícono muestra la habilidad que sugiere la ayuda de Blizzard. Tú decides qué presionar: Alfa nunca aprieta nada por ti."] = "Em combate, o ícone mostra a habilidade que a ajuda de combate da Blizzard sugere. Você decide o que apertar: o Alfa nunca aperta nada por você.",
	["En combate: espera a terminar"] = "Em combate: espere terminar",
	["En curso"] = "Em andamento",
	["En el Casco Antiguo está el SI:7, los espías y pícaros al servicio del reino."] = "Na Cidade Velha fica o SI:7, os espiões e ladinos a serviço do reino.",
	["En el Clásico mandan Thrall en Orgrimmar, Cairne en Cima del Trueno, Sylvanas en Entrañas y Vol'jin con los Lanza Negra."] = "No Clássico mandam Thrall em Orgrimmar, Cairne no Penhasco do Trovão, Sylvanas na Cidade Baixa, e Vol'jin guia os Lançanegra.",
	["En el Clásico nadie sabe dónde anda Alamuerte; los que dan la cara son sus hijos, Onyxia y Nefarian."] = "No Clássico ninguém sabe onde anda Asa da Morte; quem dá as caras são seus filhos, Onyxia e Nefarian.",
	["En el Clásico necesitas flechas o balas: lleva siempre de más en tu carcaj o tu bolsa de munición."] = "No Clássico você precisa de flechas ou balas: leve sempre de sobra na sua aljava ou bolsa de munição.",
	["En el Clásico necesitas un cuchillo de desollar en tus bolsas."] = "No Clássico você precisa de uma faca de esfolar nas bolsas.",
	["En el Clásico solo puedes tener dos profesiones principales, pero Cocina, Pesca y Primeros auxilios se aprenden aparte."] = "No Clássico você só pode ter duas profissões principais, mas Culinária, Pesca e Primeiros Socorros se aprendem à parte.",
	["En el Clásico, Costasur contra Molino Tarren era la pelea entre bandos más famosa del mundo."] = "No Clássico, Costa Sul contra Serraria Tarren era a briga entre facções mais famosa do mundo.",
	["En el Clásico, a nivel 20 aprendes a teletransportarte a las capitales, y a 40 a abrir portales para los demás."] = "No Clássico, no nível 20 você aprende a se teleportar para as capitais, e no 40 a abrir portais para os outros.",
	["En el Clásico, a nivel 20 haces la misión de los venenos; después los mejoras con tu entrenador."] = "No Clássico, no nível 20 você faz a missão dos venenos; depois os melhora com seu instrutor.",
	["En el Clásico, a nivel 40 haces la misión de tu caballo de guerra, y a 60 la cadena épica del destrero."] = "No Clássico, no nível 40 você faz a missão do seu cavalo de guerra, e no 60 a série épica do corcel.",
	["En el Clásico, a nivel 40 recibes un corcel vil, y a 60 una cadena épica en La Masacre te da uno aún más temible."] = "No Clássico, no nível 40 você recebe um corcel vil, e no 60 uma série épica em Gládio Cruel dá um ainda mais temível.",
	["En el Clásico, abrir las puertas de Ahn'Qiraj pidió un esfuerzo de guerra de todo el servidor: montañas de materiales y una cadena larguísima."] = "No Clássico, abrir os portões de Ahn'Qiraj exigiu um esforço de guerra do servidor inteiro: montanhas de materiais e uma série longuíssima.",
	["En el Clásico, algunos peces solo pican de noche o de día."] = "No Clássico, alguns peixes só mordem à noite ou de dia.",
	["En el Clásico, cada raza de sacerdote tiene un hechizo propio. Pregúntale a tu entrenador cuál te toca."] = "No Clássico, cada raça de sacerdote tem um feitiço próprio. Pergunte ao seu instrutor qual é o seu.",
	["En el Clásico, después de vendarte queda un rato en que no puedes usar otra venda."] = "No Clássico, depois de se enfaixar fica um tempo em que você não pode usar outra atadura.",
	["En el Clásico, el Cetro de las Arenas Movedizas abrió las puertas de Ahn'Qiraj tras una larguísima cadena de misiones."] = "No Clássico, o Cetro das Areias Movediças abriu os portões de Ahn'Qiraj depois de uma série de missões longuíssima.",
	["En el Clásico, el arco épico de los cazadores sale de una cadena contra demonios que empieza en el Claro de la Luna."] = "No Clássico, o arco épico dos caçadores vem de uma série contra demônios que começa na Clareira da Lua.",
	["En el Clásico, el chat de Los Baldíos era famoso por sus pláticas eternas... y por preguntar dónde estaba la esposa de Mankrik."] = "No Clássico, o chat dos Sertões era famoso pelas conversas sem fim... e por perguntar onde estava a esposa do Mankrik.",
	["En el Clásico, el nivel máximo es 60 y llegar lleva su tiempo. Por eso cada nivel se festeja."] = "No Clássico, o nível máximo é 60 e chegar lá leva tempo. Por isso cada nível se comemora.",
	["En el Clásico, el rango de honor 14 es Gran Mariscal para la Alianza y Gran Señor de la Guerra para la Horda."] = "No Clássico, a patente de honra 14 é Grão-marechal para a Aliança e Grão-senhor da Guerra para a Horda.",
	["En el Clásico, la Feria de la Luna Negra a veces se instala en Mulgore, cerca del poblado Pezuña de Sangre."] = "No Clássico, a Feira de Negraluna às vezes se instala em Mulgore, perto da Aldeia Casco Sangrento.",
	["En el Clásico, la Feria de la Luna Negra a veces se instala junto a Villadorada."] = "No Clássico, a Feira de Negraluna às vezes se instala perto de Vila d'Ouro.",
	["En el Clásico, la Horda la forman orcos, trols Lanza Negra, tauren y Renegados; la Alianza, humanos, enanos, gnomos y elfos de la noche."] = "No Clássico, a Horda é formada por orcs, trolls Lançanegra, taurens e Renegados; a Aliança, por humanos, anões, gnomos e elfos noturnos.",
	["En el Clásico, la Plaga invadió el mundo con necrópolis flotantes antes de que se abriera Naxxramas."] = "No Clássico, o Flagelo invadiu o mundo com necrópoles flutuantes antes de Naxxramas abrir.",
	["En el Clásico, la actitud defensiva se gana con una misión al nivel 10, y la rabiosa con otra al nivel 30."] = "No Clássico, a Postura Defensiva se ganha com uma missão no nível 10, e a Postura de Berserker com outra no nível 30.",
	["En el Clásico, la casa de subastas de Forjaz es la más movida de toda la Alianza."] = "No Clássico, a casa de leilões de Altaforja é a mais movimentada de toda a Aliança.",
	["En el Clásico, la forma de oso se gana con una misión a nivel 10 y la acuática con otra a nivel 16; luego vienen la felina y la de viaje."] = "No Clássico, a Forma de Urso se ganha com uma missão no nível 10 e a Aquática com outra no 16; depois vêm a de Felino e a de Viagem.",
	["En el Clásico, la montura de nivel 40 es mucho más rápida que correr, y la épica de nivel 60 todavía más."] = "No Clássico, a montaria do nível 40 é muito mais rápida que correr, e a épica do nível 60 mais ainda.",
	["En el Clásico, la tela se puede donar en tu capital a cambio de reputación."] = "No Clássico, você pode doar tecido na sua capital em troca de reputação.",
	["En el Clásico, las bandas grandes son de 40 jugadores, y Zul'Gurub y las Ruinas de Ahn'Qiraj, de 20."] = "No Clássico, as raides grandes são de 40 jogadores, e Zul'Gurub e as Ruínas de Ahn'Qiraj, de 20.",
	["En el Clásico, los Renegados se quitan el miedo, el encanto y el sueño con su voluntad."] = "No Clássico, os Renegados se livram do medo, do encanto e do sono com sua força de vontade.",
	["En el Clásico, los domingos por la tarde Bahía del Botín organizaba un concurso de pesca: ganaba quien entregara primero cuarenta peces de una especie especial."] = "No Clássico, aos domingos à tarde Angra do Butim fazia um torneio de pesca: ganhava quem entregasse primeiro quarenta peixes de uma espécie especial.",
	["En el Clásico, los enanos pueden buscar tesoros con un rastreo propio. ¡Ideal para encontrar cofres!"] = "No Clássico, os anões podem rastrear tesouros com uma habilidade própria. Ideal para achar baús!",
	["En el Clásico, los enanos se convierten en piedra para quitarse venenos y sangrados, y son buenos con las armas de fuego."] = "No Clássico, os anões viram pedra para se livrar de venenos e sangramentos, e são bons com armas de fogo.",
	["En el Clásico, los gnomos pueden ser guerreros, pícaros, magos o brujos."] = "No Clássico, os gnomos podem ser guerreiros, ladinos, magos ou bruxos.",
	["En el Clásico, los gnomos son más listos que el resto, tienen talento para la ingeniería y se zafan de lo que los inmoviliza."] = "No Clássico, os gnomos são mais espertos que o resto, têm talento para engenharia e se soltam do que os imobiliza.",
	["En el Clásico, los humanos ganan reputación más rápido gracias a su diplomacia, y tienen buen ojo para ver a los sigilosos."] = "No Clássico, os humanos ganham reputação mais rápido graças à diplomacia, e têm bom olho para ver os furtivos.",
	["En el Clásico, los maestros de armas de las capitales te enseñan a usar armas nuevas."] = "No Clássico, os mestres de armas das capitais ensinam você a usar armas novas.",
	["En el Clásico, los orcos resisten mejor los aturdimientos y sus mascotas pegan más fuerte."] = "No Clássico, os orcs resistem melhor a atordoamentos e seus ajudantes batem mais forte.",
	["En el Clásico, los tauren tienen más vida, un pisotón que aturde a los enemigos cercanos y mano verde con las hierbas."] = "No Clássico, os taurens têm mais vida, um pisão que atordoa os inimigos próximos e mão boa com ervas.",
	["En el Clásico, los trols se regeneran rápido, entran en frenesí, pegan más fuerte a las bestias y son buenos con arcos y armas arrojadizas."] = "No Clássico, os trolls se regeneram rápido, entram em frenesi, batem mais forte em feras e são bons com arcos e armas de arremesso.",
	["En el Clásico, muchas comidas te dejan bien alimentado y te suben estadísticas un buen rato."] = "No Clássico, muitas comidas deixam você bem alimentado e aumentam seus atributos por um bom tempo.",
	["En el Clásico, para pasar de 225 hay una misión de triaje en Theramore o en Sentencia."] = "No Clássico, para passar de 225 há uma missão de triagem em Theramore ou em Hammerfall.",
	["En el Clásico, quienes terminaron la cadena del cetro y tocaron el gong de Ahn'Qiraj ganaron un título y una montura únicos."] = "No Clássico, quem terminou a série do cetro e tocou o gongo de Ahn'Qiraj ganhou um título e uma montaria únicos.",
	["En el Clásico, solo elfos de la noche y tauren pueden ser druidas."] = "No Clássico, só elfos noturnos e taurens podem ser druidas.",
	["En el Clásico, solo humanos y enanos pueden ser paladines."] = "No Clássico, só humanos e anões podem ser paladinos.",
	["En el Clásico, solo orcos, trols y tauren pueden ser chamanes."] = "No Clássico, só orcs, trolls e taurens podem ser xamãs.",
	["En el Clásico, tu Reencarnación te revive a ti mismo, pero necesita un ankh en tus bolsas."] = "No Clássico, sua Reencarnação revive você mesmo, mas precisa de um ankh nas suas bolsas.",
	["En el Enclave Cenarion los druidas enseñan a los suyos el camino de la naturaleza."] = "No Enclave Cenariano os druidas ensinam aos seus o caminho da natureza.",
	["En el Festival Lunar, la gente viene al Claro de la Luna a honrar a sus ancestros."] = "No Festival da Lua, as pessoas vêm à Clareira da Lua honrar seus ancestrais.",
	["En el Festival Lunar, un emisario en las capitales te puede llevar al Claro de la Luna para celebrar con los druidas."] = "No Festival da Lua, um emissário nas capitais pode levar você à Clareira da Lua para comemorar com os druidas.",
	["En el Festival de Fuego del Solsticio de Verano hay hogueras en muchos pueblos: honrar las de tu bando da premios, y apagar las del otro también."] = "No Festival do Fogo do Solstício há fogueiras em muitos povoados: honrar as da sua facção dá prêmios, e apagar as da outra também.",
	["En el Festival de Invierno venden bolas de nieve. ¡Lánzaselas a tus amigos, que yo las atrapo!"] = "Na Festa do Véu de Inverno vendem bolas de neve. Jogue nos seus amigos, que eu pego!",
	["En el Festival de Invierno, el Gran Padre Invierno reparte regalos en Forjaz y Orgrimmar, y bajo el árbol aparecen paquetes el día 25."] = "Na Festa do Véu de Inverno, o Grande Pai Inverno distribui presentes em Altaforja e Orgrimmar, e no dia 25 aparecem pacotes embaixo da árvore.",
	["En el Festival de la Cosecha, la Horda honra a Grom Grito Infernal y la Alianza a Uther, en sus monumentos."] = "No Festival da Colheita, a Horda honra Grom Grito Infernal e a Aliança honra Uther, nos seus monumentos.",
	["En el Núcleo de Magma se desuellan perros del núcleo para un cuero muy especial."] = "No Núcleo Derretido se esfolam cães-do-núcleo para um couro muito especial.",
	["En el Santuario Esmeralda, los druidas intentan sanar el bosque enfermo."] = "No Santuário Esmeralda, os druidas tentam curar a floresta doente.",
	["En el Valle de Alterac pelean la Guardia Pico Tormenta de los enanos y el clan Lobo Gélido. Yo ya sé a quién le voy."] = "No Vale Alterac, a Guarda Lançatroz dos anões luta contra o clã Lobo do Gelo. Eu já sei para quem eu torço.",
	["En el Valle de la Fuerza están el banco y la casa de subastas: el corazón del comercio de la Horda."] = "No Vale da Força ficam o banco e a casa de leilões: o coração do comércio da Horda.",
	["En el camino"] = "No caminho",
	["En el centro de aquel Kalimdor estaba el Pozo de la Eternidad, un lago de pura magia. Unos trols que vivían a su orilla cambiaron con los siglos y se volvieron los elfos de la noche."] = "No centro daquela Kalimdor ficava a Nascente da Eternidade, um lago de magia pura. Uns trolls que viviam às suas margens mudaram com os séculos e se tornaram os elfos noturnos.",
	["En el centro de la garganta hay un enorme pozo de lava, la Caldera, donde trabajan esclavos de los Hierro Negro."] = "No centro da garganta há um enorme poço de lava, o Caldeirão, onde trabalham escravos dos Ferro Negro.",
	["En el centro del cráter humea un volcán donde viven elementales de fuego."] = "No centro da cratera fumega um vulcão onde vivem elementais de fogo.",
	["En el chat"] = "No bate-papo",
	["En el corazón del Templo de la Luna hay un pozo lunar, donde las sacerdotisas rezan a Elune."] = "No coração do Templo da Lua há um poço lunar, onde as sacerdotisas rezam a Eluna.",
	["En el cráter, un tal Linken perdió la memoria y busca su espada y su escudo: un guiño a cierto héroe de orejas puntiagudas."] = "Na cratera, um tal de Linken perdeu a memória e procura sua espada e seu escudo: uma piscadela para certo herói de orelhas pontudas.",
	["En el este de las Tierras Inhóspitas viven dragones negros y sus siervos. Pasa lejitos si no llevas compañía."] = "No leste dos Ermos vivem dragões negros e seus servos. Passe longe se estiver sem companhia.",
	["En el este del lago viven ogros que les hacen la vida difícil a los enanos de Thelsamar."] = "No leste do lago vivem ogros que tornam a vida difícil para os anões de Thelsamar.",
	["En el gran salar del este, goblins y gnomos organizan carreras; la rivalidad es feroz."] = "Na grande salina do leste, goblins e gnomos organizam corridas; a rivalidade é feroz.",
	["En el juego"] = "No jogo",
	["En el lago de Villa del Lago hay múrlocs, ¡como en casi todo lago de Azeroth!"] = "No lago de Vila Plácida há murlocs, como em quase todo lago de Azeroth!",
	["En el mapa"] = "No mapa",
	["En el mapa de Alfa, clic: seguirla con la flecha o guardarla como marcador."] = "No mapa do Alfa, clique: segui-la com a seta ou salvá-la como marcador.",
	["En el mapa del mundo"] = "No mapa-múndi",
	["En el marco del objetivo"] = "No quadro do alvo",
	["En el minimapa"] = "No minimapa",
	["En el mundo"] = "No mundo",
	["En el nivel 10 domas tu bestia."] = "No nível 10 você doma sua fera.",
	["En el nivel 20 aprendes venenos."] = "No nível 20 você aprende venenos.",
	["En el norte de estas tierras, la Cruzada Escarlata domina un pueblo amurallado y lo defiende con fanatismo."] = "No norte destas terras, a Cruzada Escarlate domina um povoado murado e o defende com fanatismo.",
	["En el oeste de Las Mil Agujas anidan dracoleones salvajes."] = "No oeste de Mil Agulhas fazem ninho serpes selvagens.",
	["En el pueblo de los druidas del Claro de la Luna conviven Alianza y Horda: el Círculo Cenarion recibe a todos."] = "Na vila dos druidas da Clareira da Lua convivem Aliança e Horda: o Círculo Cenariano recebe todos.",
	["En el sur de Desolace, demonios y sátiros se reúnen en un aquelarre."] = "No sul de Desolação, demônios e sátiros se reúnem num sabá.",
	["En el sur de Tanaris hay colmenas de silítidos, primos de los de Silithus."] = "No sul de Tanaris há colmeias de silitídeos, primos dos de Silithus.",
	["En el sureste, la Mano de Tyr es la ciudad más fuerte que le queda a la Cruzada Escarlata."] = "No sudeste, a Mão de Tyr é a cidade mais forte que resta à Cruzada Escarlate.",
	["En espera"] = "Em espera",
	["En esta zona"] = "Nesta zona",
	["En estas laderas está Durnholde, donde Aedelas Blackmoore crió a Thrall como gladiador."] = "Nestas encostas fica Durnholde, onde Aedelas Blackmoore criou Thrall como gladiador.",
	["En estas tierras cayó Anduin Lothar, el León de Azeroth, durante la Segunda Guerra."] = "Nestas terras caiu Anduin Lothar, o Leão de Azeroth, durante a Segunda Guerra.",
	["En estas tierras estuvo Strom, la capital de Arathor, el primer gran reino humano."] = "Nestas terras ficava Strom, a capital de Arathor, o primeiro grande reino humano.",
	["En este pantano se hundió el Templo de Atal'Hakkar: los dragones verdes lo hundieron para frenar a los sacerdotes de Hakkar."] = "Neste pântano afundou o Templo de Atal'Hakkar: os dragões verdes o afundaram para deter os sacerdotes de Hakkar.",
	["En grifo, la línea de tu vuelo en el mapa: por dónde vas, dónde aterrizas y el tiempo que falta."] = "De grifo, a linha do seu voo no mapa: por onde você vai, onde vai pousar e o tempo que falta.",
	["En grupo"] = "Em grupo",
	["En grupo casi siempre hay varios enemigos: pegas a dos a la vez."] = "Em grupo quase sempre há vários inimigos: você bate em dois de uma vez.",
	["En grupo y aguantando: Furia justa te da más amenaza."] = "Em grupo e tanquando: Fúria Justa dá mais ameaça.",
	["En grupo, al seleccionar un raro sin marca, Alfa te ofrece ponerle la calavera con un clic: todo tu grupo la ve. En banda, si eres líder o ayudante."] = "Em grupo, ao selecionar um raro sem marca, o Alfa oferece colocar a caveira nele com um clique: todo o seu grupo vê. Em raide, se você for líder ou assistente.",
	["En grupo, cura al tanque antes que a nadie."] = "Em grupo, cure o tanque antes de qualquer um.",
	["En grupo, cura al tanque primero y no saques monstruos tú."] = "Em grupo, cure o tanque primeiro e não puxe monstros você mesmo.",
	["En grupo, cura antes de que la vida baje mucho: es más barato."] = "Em grupo, cure antes que a vida baixe muito: sai mais barato.",
	["En grupo, deja tus tótems de maná y de curas cerca del grupo."] = "Em grupo, deixe seus totens de mana e de cura perto do grupo.",
	["En la %s"] = "Na %s",
	["En la Arena Gurubashi aparece de vez en cuando un cofre que todos se pelean. ¡Sálvese quien pueda!"] = "Na Arena Gurubashi aparece de vez em quando um baú que todos disputam. Salve-se quem puder!",
	["En la Enciclopedia"] = "Na Enciclopédia",
	["En la Feria canjeas vales por premios; los vales se ganan entregando cosas que hiciste con tu profesión o que juntaste cazando."] = "Na Feira você troca bilhetes por prêmios; os bilhetes se ganham entregando coisas que fez com sua profissão ou juntou caçando.",
	["En la Feria de la Luna Negra, la adivina Sayge te hace unas preguntas y te da una fortuna que sube tus estadísticas un buen rato."] = "Na Feira de Negraluna, a vidente Sayge faz umas perguntas e dá uma sorte que aumenta seus atributos por um bom tempo.",
	["En la Fortaleza de Grommash, Thrall recibe a quien venga; muy cerca está Eitrigg, el viejo orco amigo de Tirion."] = "Na Fortaleza Grommash, Thrall recebe quem vier; bem perto fica Eitrigg, o velho orc amigo de Tirion.",
	["En la Guerra de las Arenas Movedizas, el archidruida Fandral perdió a su hijo Valstann a manos de los qiraji."] = "Na Guerra das Areias Movediças, o arquidruida Fandral perdeu seu filho Valstann para os qiraji.",
	["En la Segunda Guerra, la Horda sumó a los trols Amani, a los ogros y a dragones rojos esclavizados."] = "Na Segunda Guerra, a Horda ganhou os trolls Amani, os ogros e dragões vermelhos escravizados.",
	["En la Semana de los Niños, los huérfanos de Ventormenta y Orgrimmar te piden que los lleves de paseo; al final te dan una mascota."] = "Na Semana das Crianças, os órfãos de Ventobravo e Orgrimmar pedem que você os leve para passear; no final dão um mascote.",
	["En la Tercera Guerra, orcos, humanos y elfos se unieron aquí contra Archimonde, y Nordrassil sacrificó su energía para destruirlo."] = "Na Terceira Guerra, orcs, humanos e elfos se uniram aqui contra Archimonde, e Nordrassil sacrificou sua energia para destruí-lo.",
	["En la Terraza de los Artesanos de Darnassus están los maestros de profesiones."] = "No Terraço dos Artesãos de Darnassus ficam os instrutores de profissões.",
	["En la Vega se encuentran páginas sueltas de un libro de Nesingwary; junta un capítulo completo y llévaselo."] = "Na Selva do Espinhaço se encontram páginas soltas de um livro de Nesingwary; junte um capítulo completo e leve para ele.",
	["En la batalla de Hyjal, Malfurion hizo sonar el Cuerno de Cenarius y miles de fuegos fatuos rodearon a Archimonde hasta destruirlo."] = "Na batalha de Hyjal, Malfurion tocou a Trompa de Cenarius e milhares de fogos-fátuos cercaram Archimonde até destruí-lo.",
	["En la casa de subastas, mira los precios unos días antes de vender: cambian según la hora y quién esté jugando."] = "Na casa de leilões, observe os preços uns dias antes de vender: eles mudam conforme a hora e quem está jogando.",
	["En la cima del Monte Hyjal crece Nordrassil, el Árbol del Mundo, que los dragones bendijeron."] = "No topo do Monte Hyjal cresce Nordrassil, a Árvore do Mundo, abençoada pelos dragões.",
	["En la costa de Durotar, soldados de Kul Tiras ocupan el Fuerte Tiragarde: una espina clavada en la tierra de la Horda."] = "Na costa de Durotar, soldados de Kul Tiraz ocupam a Fortaleza Tiragarde: um espinho cravado na terra da Horda.",
	["En la costa de Tanaris se esconden piratas de los Mares del Sur."] = "Na costa de Tanaris se escondem piratas dos Mares do Sul.",
	["En la costa del pantano hay naga, y no reciben bien a los curiosos."] = "Na costa do pântano há nagas, e elas não recebem bem os curiosos.",
	["En la costa este vive una tribu trol amiga de la Horda, enemiga de los trols de Jintha'Alor."] = "Na costa leste vive uma tribo troll amiga da Horda e inimiga dos trolls de Jintha'Alor.",
	["En la costa oeste de Vallefresno, las Cavernas de Brazanegra fueron un templo de Elune; hoy están hundidas y llenas de naga."] = "Na costa oeste do Vale Gris, as Profundezas Negras foram um templo de Eluna; hoje estão afundadas e cheias de nagas.",
	["En la costa se ven ruinas de antiguos palacios élficos, medio hundidos en el mar."] = "Na costa se veem ruínas de antigos palácios élficos, meio afundados no mar.",
	["En la cueva del barco hay muchos piratas: no bajen todos de golpe al muelle."] = "Na caverna do navio há muitos piratas: não desçam todos de uma vez até o cais.",
	["En la excavación de Ironband, los troggs salieron de la tierra y se quedaron con todo."] = "Na escavação de Ironband, os troggs saíram da terra e ficaram com tudo.",
	["En la ficha de cada mazmorra está el botín de cada jefe y lo que mejora tu equipo."] = "Na ficha de cada masmorra estão o saque de cada chefe e o que melhora seu equipamento.",
	["En la granja de los Saldean, la vieja yegua Blanchy necesita avena. Es de las misiones más tiernitas de los Páramos."] = "Na fazenda dos Saldean, a velha égua Blanchy precisa de aveia. É uma das missões mais fofas do Cerro Oeste.",
	["En la guarida de Onyxia, a los lados hay nidos con huevos: si alguien los pisa salen dragoncitos... muchísimos."] = "No covil de Onyxia, nos lados há ninhos com ovos: se alguém pisa neles, saem dragõezinhos... muitíssimos.",
	["En la pelea, el juego te avisa"] = "Na luta, o jogo avisa você",
	["En la sala de la Liga de Expedicionarios de Forjaz hay biblioteca, mapas y un museo con fósiles gigantes."] = "No salão da Liga dos Exploradores de Altaforja há biblioteca, mapas e um museu com fósseis gigantes.",
	["En la segunda parte mátenla a ella primero: cura mucho."] = "Na segunda parte, matem ela primeiro: ela cura muito.",
	["En la subasta cuenta el precio más bajo que vio, menos la comisión (%d%%, estimada). Al desencantar usa tablas del juego clásico, también estimadas."] = "No leilão, conta o menor preço que viu, menos a taxa (%d%%, estimada). Para desencantar, usa tabelas do jogo clássico, também estimadas.",
	["En la subasta, unos %s."] = "No leilão, uns %s.",
	["En la ventana y aquí. Si no estás entre ellos, tu fila sale al final."] = "Na janela e aqui. Se você não estiver entre eles, sua linha aparece no final.",
	["En las Cuevas de los Lamentos, el druida Naralex soñó con devolverle el verdor a Los Baldíos, y su sueño se volvió pesadilla."] = "Na Caverna Ululante, o druida Naralex sonhou em devolver o verde aos Sertões, e seu sonho virou pesadelo.",
	["En las Guerras Trol, los altos elfos enseñaron magia a cien humanos para vencer juntos a los Amani. Fueron los primeros magos de la humanidad."] = "Nas Guerras Trolls, os altos elfos ensinaram magia a cem humanos para vencerem juntos os Amani. Foram os primeiros magos da humanidade.",
	["En las Mazmorras de Ventormenta los presos se amotinaron, y la guardia pide ayuda para calmar el desastre."] = "No Cárcere de Ventobravo os presos se amotinaram, e a guarda pede ajuda para acalmar a bagunça.",
	["En las Pozas de la Visión, bajo una de las mesetas, entrenan los magos y sacerdotes Renegados."] = "Nos Poços da Visão, sob um dos planaltos, treinam os magos e sacerdotes Renegados.",
	["En las cuevas de Cuna del Invierno viven yetis peludos y gruñones."] = "Nas cavernas de Hibérnia vivem yetis peludos e resmungões.",
	["En las cuevas de Feralas viven yetis, y los ogros Gordunni tienen sus campamentos en el norte."] = "Nas cavernas de Feralas vivem yetis, e os ogros Gordunni têm seus acampamentos no norte.",
	["En las cuevas nevadas de Dun Morogh viven trols de las nieves que no quieren a los enanos ni tantito."] = "Nas cavernas nevadas de Dun Morogh vivem trolls do gelo que não gostam nem um pouquinho dos anões.",
	["En las dos armas"] = "Nas duas armas",
	["En las granjas del oeste hay calderos de la Plaga que siguen esparciendo la peste; la Alianza manda aventureros a destruirlos."] = "Nas fazendas do oeste há caldeirões do Flagelo que continuam espalhando a peste; a Aliança manda aventureiros destruí-los.",
	["En las ruinas de la ciudad de Alterac hoy mandan los ogros y el Sindicato, la banda de nobles caídos del viejo reino."] = "Nas ruínas da cidade de Alterac hoje mandam os ogros e o Sindicato, o bando de nobres caídos do velho reino.",
	["En lo alto de la sierra hay un pico sagrado para los druidas elfos, donde anidan aves enormes."] = "No alto da serra há um pico sagrado para os druidas elfos, onde aninham aves enormes.",
	["En lo más alto de la Montaña Roca Negra manda Nefarian, hijo de Alamuerte."] = "No ponto mais alto da Montanha Rocha Negra manda Nefarian, filho de Asa da Morte.",
	["En los mapas"] = "Nos mapas",
	["En lugar de las del juego"] = "No lugar das do jogo",
