	["En memoria de una gran perrita"] = "Em memória de uma cachorrinha incrível",
	["En mi zona"] = "Na minha zona",
	["En movimiento"] = "Em movimento",
	["En orco, «Lok'tar ogar» quiere decir «victoria o muerte»."] = "Em órquico, «Lok'tar ogar» quer dizer «vitória ou morte».",
	["En otra zona: %s"] = "Em outra zona: %s",
	["En pantalla"] = "Na tela",
	["En pausa"] = "Em pausa",
	["En pausa dentro de la instancia"] = "Pausado dentro da instância",
	["En pausa por ahora"] = "Pausado por enquanto",
	["En pausa: hay otro addon de pesca activo"] = "Em pausa: há outro addon de pesca ativo",
	["En plena Segunda Guerra, Gul'dan abandonó a la Horda para buscar la Tumba de Sargeras. Ahí lo despedazaron los demonios que encontró."] = "Em plena Segunda Guerra, Gul'dan abandonou a Horda para buscar a Tumba de Sargeras. Lá os demônios que encontrou o despedaçaram.",
	["En posadas y ciudades acumulas XP descansada: ganas el doble de XP por enemigo hasta gastarla. Si cierras sesión aquí, también se acumula."] = "Em estalagens e cidades você acumula XP de descanso: ganha o dobro de XP por inimigo até gastá-la. Se sair do jogo aqui, ela também se acumula.",
	["En posadas y ciudades juntas XP descansada: ganas el doble por enemigo hasta gastarla."] = "Em estalagens e cidades você acumula XP de descanso: ganha o dobro por inimigo até gastá-la.",
	["En qué orden aparecen."] = "Em que ordem eles aparecem.",
	["En qué se gastan"] = "Em que se gastam",
	["En silencio"] = "Em silêncio",
	["En solitario es lento: usa la varita para rematar."] = "Sozinho é lento: use a varinha para acabar com eles.",
	["En solitario, deja curas que duran en el tiempo y pelea con Cólera."] = "Sozinho, aplique curas que duram ao longo do tempo e lute com Ira.",
	["En solitario, pelea con choques y cúrate entre monstruos."] = "Sozinho, lute com choques e cure-se entre um monstro e outro.",
	["En su ficha toca «Agregar a mi ruta»."] = "Na ficha dele, toque em “Adicionar à minha rota”.",
	["En sus inicios, una batalla del Valle de Alterac podía durar horas... ¡y hasta días!"] = "No começo, uma batalha do Vale Alterac podia durar horas... e até dias!",
	["En todo Alfa"] = "Em todo o Alfa",
	["En total, %d cosas por unos %s."] = "No total, %d coisas por cerca de %s.",
	["En total: %s"] = "No total: %s",
	["En tu arma"] = "Na sua arma",
	["En tu marco"] = "No seu quadro",
	["En tu plan"] = "No seu plano",
	["En tu registro"] = "No seu registro",
	["En tus bolsas"] = "Nas suas bolsas",
	["En tus bolsas, el botín, el chat o cualquier enlace: Alt+clic abre la guía para conseguirlo o, si no hay, su ficha en la enciclopedia."] = "Nas suas bolsas, no saque, no chat ou em qualquer link: Alt+clique abre o guia para consegui-lo ou, se não houver, a ficha dele na enciclopédia.",
	["En tus bolsas: úsala para aprenderla"] = "Nas suas bolsas: use-a para aprendê-la",
	["En un aviso"] = "Num aviso",
	["En un aviso y en el chat"] = "Num aviso e no bate-papo",
	["En un cañón de Vallefresno, Grom mató al señor demonio Mannoroth y liberó a los orcos de su sangre maldita."] = "Num cânion do Vale Gris, Grom matou o senhor demônio Mannoroth e libertou os orcs do seu sangue amaldiçoado.",
	["En un valle de Frondavil cayeron infernales del cielo, y todavía se ven sus cráteres."] = "Num vale da Selva Maleva caíram infernais do céu, e ainda se veem suas crateras.",
	["En un vuelo con escalas, una línea bajo el temporizador dice dónde es la siguiente parada y cuánto falta para llegar. Necesita el temporizador de vuelo encendido."] = "Num voo com escalas, uma linha embaixo do cronômetro diz onde é a próxima parada e quanto falta para chegar. Precisa do cronômetro de voo ativado.",
	["En una aldea del sur del bosque, los vecinos parecen normales de día... y de noche se convierten en worgen."] = "Numa aldeia do sul da floresta, os moradores parecem normais de dia... e à noite viram worgens.",
	["En una de las mesetas, los tauren honran a los espíritus de sus ancestros."] = "Em um dos planaltos, os taurens honram os espíritos de seus ancestrais.",
	["En una instancia: la flecha vuelve al salir"] = "Numa instância: a seta volta quando você sair",
	["En una isla de Azshara vive el duque Hydraxis, señor del agua; su gente te ayuda a apagar las runas del Núcleo de Magma."] = "Numa ilha de Azshara vive o duque Hydraxis, senhor da água; seu povo ajuda você a apagar as runas do Núcleo Derretido.",
	["En una mazmorra no hay guaridas."] = "Não há tocas dentro de uma masmorra.",
	["En una pestaña nueva"] = "Numa aba nova",
	["En unos segundos aparece tu build."] = "Em alguns segundos sua build aparece.",
	["En uso"] = "Em uso",
	["En uso, a tu gusto"] = "Em uso, do seu jeito",
	["En vivo"] = "Ao vivo",
	["En vivo si estás con un banquero; si no, la última foto."] = "Ao vivo se você estiver com um bancário; senão, a última foto.",
