	["Error"] = "Erro",
	["Errores de Lua de Alfa en esta sesión:"] = "Erros de Lua do Alfa nesta sessão:",
	["Errores de Lua de Alfa en esta sesión: ninguno"] = "Erros de Lua do Alfa nesta sessão: nenhum",
	["Es corta y está dentro de Ventormenta. Los presos están en celdas a los lados: avancen despacio."] = "É curta e fica dentro de Ventobravo. Os presos estão em celas dos dois lados: avancem devagar.",
	["Es de la otra facción"] = "É da outra facção",
	["Es de una misión."] = "É de uma missão.",
	["Es el jefe que pide una misión de la Alianza: revisa tus misiones antes de entrar."] = "É o chefe que uma missão da Aliança pede: confira suas missões antes de entrar.",
	["Es el primer jefe y es sencillo. Al morir, el prisionero de tu facción abre la puerta del patio."] = "É o primeiro chefe e é simples. Quando ele morre, o prisioneiro da sua facção abre a porta do pátio.",
	["Es el primer reto: con él se abre el Legado."] = "É o primeiro desafio: com ele o Legado é liberado.",
	["Es el punto %d de %d de tu build."] = "É o ponto %d de %d da sua build.",
	["Es el que toca ahora."] = "É o da vez agora.",
	["Es el último del Cementerio. Lanza llamas a su alrededor: si peleas de lejos, quédate lejos."] = "É o último do Cemitério. Lança chamas ao redor: se você luta à distância, fique longe.",
	["Es el único lobo a la vista."] = "É o único lobo à vista.",
	["Es grande y es fácil perderse: sigan a una sola persona y no corran solos."] = "É grande e fácil de se perder: sigam uma única pessoa e não corram sozinhos.",
	["Es la máquina de Sneed: rómpela y él saldrá a pelear."] = "É a máquina do Sneed: quebre-a e ele sai para lutar.",
	["Es la primera mazmorra de la Horda: corta y buena para aprender a jugar en grupo."] = "É a primeira masmorra da Horda: curta e boa para aprender a jogar em grupo.",
	["Es la primera mazmorra grande de la Alianza: avancen despacio y tiren un grupo a la vez."] = "É a primeira masmorra grande da Aliança: avancem devagar e puxem um grupo de cada vez.",
	["Es la que más vale al venderla."] = "É a que vale mais para vender.",
	["Es larga y tiene dos entradas. Muchos enemigos son de piedra y pegan fuerte."] = "É longa e tem duas entradas. Muitos inimigos são de pedra e batem forte.",
	["Es larga y tiene muchos robots: algunos ponen bombas o hacen sonar alarmas que traen más enemigos."] = "É longa e tem muitos robôs: alguns colocam bombas ou tocam alarmes que trazem mais inimigos.",
	["Es lento: si peleas de lejos, atácalo mientras se acerca."] = "Ele é lento: se você luta à distância, ataque enquanto ele se aproxima.",
	["Es muy veloz: frénalo si tu clase puede."] = "Ele é muito rápido: deixe-o lento se a sua classe puder.",
	["Es opcional. Si dices que sí, los lobos de La Jauría que usan Alfa ven a tu personaje en el mapa de WoW, como ves a tu grupo, y pueden llegar a donde estás con la flecha; y tú a ellos. Alfa solo comparte dónde anda tu personaje dentro del juego: la zona, el punto en el mapa, su nivel y su clase. Nada de tu ubicación real, tu computadora ni tu cuenta."] = "É opcional. Se você disser sim, os lobos de La Jauría que usam o Alfa veem seu personagem no mapa do WoW, como você vê seu grupo, e podem chegar até você com a seta; e você até eles. O Alfa só compartilha onde seu personagem anda dentro do jogo: a zona, o ponto no mapa, o nível e a classe. Nada da sua localização real, do seu computador nem da sua conta.",
	["Es opcional: tu personaje aparece en el mapa de WoW de los lobos de La Jauría que usan Alfa, y ellos en el tuyo, para encontrarse y llegar con la flecha. Solo se comparte dónde anda tu personaje dentro del juego (zona, punto en el mapa, nivel y clase), nunca tu ubicación real ni nada de tu computadora, y nunca dentro de mazmorras. Va por un canal oculto que no sale en el chat, aunque alguien que entre a él con otro addon podría verlo. Tu grupo se ve siempre. Lo cambias cuando quieras en La Jauría."] = "É opcional: seu personagem aparece no mapa de WoW dos lobos de La Jauría que usam o Alfa, e eles no seu, para se encontrarem e chegarem com a seta. Só é compartilhado onde seu personagem está dentro do jogo (zona, ponto no mapa, nível e classe), nunca sua localização real nem nada do seu computador, e nunca dentro de masmorras. Vai por um canal oculto que não aparece no chat, embora alguém que entre nele com outro addon possa ver. Seu grupo sempre aparece. Mude quando quiser em La Jauría.",
	["Es para niveles %s y vas en el %d: te faltan %d niveles."] = "É para os níveis %s e você está no %d: faltam %d níveis.",
	["Es para otra raza."] = "É para outra raça.",
	["Es raro del Cementerio y no siempre aparece."] = "É um raro do Cemitério e nem sempre aparece.",
	["Es raro del Cementerio y no siempre aparece. Envenena: quita el veneno."] = "É um raro do Cemitério e nem sempre aparece. Ele envenena: remova o veneno.",
	["Es raro del Cementerio y no siempre aparece. Puede silenciar a quien lanza hechizos."] = "É um raro do Cemitério e nem sempre aparece. Pode silenciar quem lança feitiços.",
	["Es raro y aparece pocas veces. Usa fuego a su alrededor."] = "É raro e aparece poucas vezes. Usa fogo ao redor.",
	["Es raro y está en una cueva escondida. Es un murciélago que pega rápido."] = "É raro e fica numa caverna escondida. É um morcego que bate rápido.",
	["Es raro y no siempre aparece. Pega muy fuerte para su nivel: tírenlo con cuidado."] = "É raro e nem sempre aparece. Bate muito forte para o nível dele: puxem com cuidado.",
	["Es raro y no siempre está. Golpea fuerte a todos los que tiene enfrente."] = "É raro e nem sempre está lá. Bate forte em todos que estão na frente dele.",
	["Es raro. Pone un tótem de tierra: rómpelo."] = "É raro. Coloca um totem de terra: quebre-o.",
	["Es raro: no siempre está. Duerme a los jugadores y explota con magia a su alrededor."] = "É raro: nem sempre está lá. Põe os jogadores para dormir e explode com magia ao redor.",
	["Es sencillo: buen momento para beber agua antes del último jefe."] = "É simples: um bom momento para beber água antes do último chefe.",
	["Es un brujo que lanza hechizos: interrúmpelo si tu clase puede (Patada, Golpe de escudo, Choque de tierra...)."] = "É um bruxo que lança feitiços: interrompa se a sua classe puder (Chute, Shield Bash, Choque Terreno...).",
	["Es un chamán con tótems: rompan los tótems, son fáciles de matar."] = "É um xamã com totens: quebrem os totens, eles morrem fácil.",
	["Es un enano con escudo: aguanta mucho pero no tiene trucos."] = "É um anão com escudo: aguenta muito, mas não tem truques.",
	["Es un enemigo fuerte de la mina: trátenlo como un jefe pequeño."] = "É um inimigo forte da mina: tratem-no como um chefe pequeno.",
	["Es un grupo: cada uno suelta su propio botín."] = "É um grupo: cada um deixa cair o próprio saque.",
	["Es un paladín: se cura con luz sagrada. Interrumpe su curación."] = "É um paladino: ele se cura com luz sagrada. Interrompa a cura dele.",
	["Es un sátiro rápido que envenena: si tu clase quita venenos, úsalo."] = "É um sátiro rápido que envenena: se a sua classe remove venenos, use.",
	["Es un trogg que lanza rayos: interrúmpelo."] = "É um trogg que lança raios: interrompa.",
	["Es una mejora para ti"] = "É uma melhoria para você",
	["Es una mejora para ti."] = "É uma melhoria para você.",
	["Es una montura de tu clase: pregunta a tu instructor de clase cuándo y cómo se consigue."] = "É uma montaria da sua classe: pergunte ao instrutor da sua classe quando e como consegui-la.",
	["Es una tortuga gigante con mucha armadura: pega lento pero duro."] = "É uma tartaruga gigante com muita armadura: bate devagar, mas forte.",
	["Es una tortuga muy dura, pero solo golpea: no tiene trucos."] = "É uma tartaruga muito resistente, mas só bate: não tem truques.",
	["Esa cadena no trae ninguna estadística que Alfa puntúe."] = "Esse código não traz nenhum atributo que o Alfa pontue.",
	["Esa fila todavía no se abre: faltan puntos en esa rama."] = "Essa fileira ainda não abre: faltam pontos nesse ramo.",
	["Esa tecla ya tiene dueño"] = "Essa tecla já tem dono",
	["Esa ya me la diste, ¡gracias! Guárdame la siguiente."] = "Essa você já me deu, obrigada! Guarde a próxima pra mim.",
