	["Las Montañas Crestagrana deben su nombre a sus rocas rojizas."] = "As Montanhas Cristarrubra devem seu nome às rochas avermelhadas.",
	["Las Profundidades de Roca Negra son una ciudad enana entera bajo la montaña: la capital de los Hierro Negro."] = "O Abismo Rocha Negra é uma cidade anã inteira sob a montanha: a capital dos Ferro Negro.",
	["Las Rocas Rojas de Mulgore son un lugar sagrado: ahí descansan los ancestros de los tauren."] = "As Rochas Vermelhas de Mulgore são um lugar sagrado: ali descansam os ancestrais dos taurens.",
	["Las Rocas Rojas son el lugar más sagrado de Mulgore: ahí descansan los ancestros de tu gente."] = "As Rochas Vermelhas são o lugar mais sagrado de Mulgore: ali descansam os ancestrais do seu povo.",
	["Las aguas de nivel 20 a 35. El rango Experto se aprende con el libro que vende el pescador de Bahía del Botín."] = "As águas de nível 20 a 35. A faixa Especialista se aprende com o livro que o pescador de Angra do Butim vende.",
	["Las barras de abajo"] = "As barras de baixo",
	["Las bendiciones mayores duran más y cubren a toda una clase del grupo. ¡Ahorran mucho maná!"] = "As bênçãos maiores duram mais e cobrem uma classe inteira do grupo. Economizam muita mana!",
	["Las bolsas de Alfa acomodan todo por categorías, marcan lo nuevo y lo de misión, y depositan rápido en el banco."] = "As bolsas do Alfa organizam tudo por categoria, marcam o novo e o de missão, e depositam rápido no banco.",
	["Las bolsas que coses siempre se venden: todo el mundo quiere más espacio."] = "As bolsas que você costura sempre vendem: todo mundo quer mais espaço.",
	["Las bombas y granadas te salvan en mazmorras y en peleas contra el otro bando."] = "As bombas e granadas salvam você em masmorras e em lutas contra o outro lado.",
	["Las cajas cerradas las abren los pícaros; ofrécelas en el chat y a veces hasta te regalan el servicio."] = "As caixas trancadas são abertas pelos ladinos; ofereça no chat e às vezes eles até fazem de graça.",
	["Las cartas de la Luna Negra caen de enemigos por todo el mundo; un mazo completo se cambia en la Feria por un abalorio poderoso."] = "As cartas de Negraluna caem de inimigos pelo mundo todo; um baralho completo se troca na Feira por um berloque poderoso.",
	["Las casas de subastas neutrales de Bahía del Botín, Gadgetzan y Vista Eterna cobran más comisión, pero te dejan comerciar con el otro bando."] = "As casas de leilões neutras de Angra do Butim, Gadgetzan e Visteterna cobram mais comissão, mas deixam você negociar com o outro lado.",
	["Las centinelas de Vallefresno pelean sin descanso contra los leñadores orcos de Grito de Guerra."] = "As sentinelas do Vale Gris lutam sem descanso contra os lenhadores orcs Brado Guerreiro.",
	["Las centinelas domestican sables de hielo en Cuna del Invierno, y se los confían solo a quien se gana su respeto."] = "As sentinelas domesticam sabres-gélidos em Hibérnia e só os confiam a quem conquista seu respeito.",
	["Las citas de la manada están apagadas (Ajustes de La Jauría)."] = "Os encontros da matilha estão desligados (Ajustes de La Jauría).",
	["Las citas van a los lobos de tu hermandad: necesitas una."] = "Os encontros vão para os lobos da sua guilda: você precisa de uma.",
	["Las criaturas que invocan los enemigos por un rato."] = "As criaturas que os inimigos invocam por um tempo.",
	["Las cuentas"] = "As contas",
	["Las cuentas de prueba no pueden compartir: el juego no lo permite."] = "As contas de teste não podem compartilhar: o jogo não permite.",
	["Las de tu ruta, las de la guía o todas: se eligen en Ajustes > Misiones, con lo demás de las misiones."] = "As da sua rota, as do guia ou todas: escolha em Ajustes > Missões, com o resto das missões.",
	["Las demás"] = "As demais",
	["Las demás ranuras"] = "Os demais espaços",
	["Las dos se suben solas mientras matas y viajas, y lo que juntas se vende bien: oro para tu montura y tus habilidades."] = "As duas sobem sozinhas enquanto você mata e viaja, e o que você junta vende bem: ouro para sua montaria e suas habilidades.",
	["Las dríades son hijas de Cenarius, y los guardianes de la arboleda, sus hijos."] = "As dríades são filhas de Cenarius, e os guardiões do bosque, seus filhos.",
	["Las esquinas de la pantalla se oscurecen poco a poco, como en una foto."] = "Os cantos da tela escurecem aos poucos, como numa foto.",
	["Las excavaciones de los enanos despertaron a los troggs, y ahora Thelsamar tiene que cuidarse de ellos."] = "As escavações dos anões despertaram os troggs, e agora Thelsamar precisa se cuidar deles.",
	["Las explicaciones vuelven a salir."] = "As explicações voltam a aparecer.",
	["Las flores cantoras corrompidas de Frondavil se pueden purificar; al hacerlo te dan una bendición que dura un buen rato."] = "As flores-cantoras corrompidas da Selva Maleva podem ser purificadas; ao fazer isso você ganha uma bênção que dura um bom tempo.",
	["Las fronteras entre zonas ya no parpadean al mover el mapa."] = "As fronteiras entre as zonas não piscam mais ao mover o mapa.",
	["Las gafas de ingeniero solo las pueden usar ingenieros: ¡lúcelas con orgullo!"] = "Os óculos de engenheiro só podem ser usados por engenheiros: use com orgulho!",
	["Las hierbas de nivel alto se venden muy bien en la casa de subastas."] = "As ervas de nível alto vendem muito bem na casa de leilões.",
	["Las líneas que escribe Anunciar en el chat de tu grupo o banda."] = "As linhas que Anunciar escreve no chat do seu grupo ou raide.",
	["Las marca con una flecha."] = "As melhorias ganham uma seta.",
	["Las marcas de la manada también en el minimapa, no solo en el mapa del mundo."] = "As marcas da matilha também no minimapa, não só no mapa-múndi.",
	["Las marcas en el suelo de hechizos y áreas. Apagarlas esconde avisos de combate: mejor dejarlas encendidas."] = "As marcas no chão de feitiços e áreas. Desligá-las esconde avisos de combate: melhor deixá-las ligadas.",
	["Las mejores misiones que ya puedes tomar cerca de ti, en el orden más corto."] = "As melhores missões que você já pode pegar perto de você, na ordem mais curta.",
	["Las mesetas de Cima del Trueno están unidas por puentes, y a la ciudad se sube en elevadores."] = "Os planaltos do Penhasco do Trovão são unidos por pontes, e se sobe à cidade por elevadores.",
	["Las metas se cumplen solas al hacerlas; las notas las marcas tú. Ordénalas como quieras."] = "As metas se cumprem sozinhas quando você as faz; as notas você marca. Ordene como quiser.",
	["Las misiones avisan otra vez"] = "As missões avisam de novo",
	["Las misiones de Molino Tarren mandan a la Horda contra las granjas humanas de las laderas."] = "As missões da Serraria Tarren mandam a Horda contra as fazendas humanas dos contrafortes.",
	["Las misiones grises dan poca XP. Entrégalas y sigue adelante."] = "As missões cinzas dão pouca XP. Entregue e siga em frente.",
	["Las misiones previas y el nivel que pide, para poder tomarla."] = "As missões anteriores e o nível que pede, para poder pegá-la.",
	["Las misiones que más experiencia dan cerca de ti."] = "As missões que dão mais experiência perto de você.",
	["Las misiones repetibles de reputación, como entregar tela, también son una forma de farmeo."] = "As missões repetíveis de reputação, como entregar tecido, também são uma forma de farm.",
	["Las monturas de los gnomos son mecazancudos, aves mecánicas que ellos mismos inventaron."] = "As montarias dos gnomos são mecanostruzes, aves mecânicas que eles mesmos inventaram.",
	["Las monturas de otra raza de tu bando pueden pedir reputación con su ciudad: la de tu raza siempre se puede."] = "As montarias de outra raça da sua facção podem pedir reputação com a cidade dela: as da sua raça sempre estão disponíveis.",
	["Las monturas de tu raza"] = "As montarias da sua raça",
	["Las monturas épicas del Clásico cuestan bastante oro; juntarlo poco a poco es parte de la aventura."] = "As montarias épicas do Clássico custam bastante ouro; juntar aos poucos faz parte da aventura.",
	["Las notas del lobo están apagadas (Ajustes de La Jauría)."] = "As notas do lobo estão desligadas (Ajustes de La Jauría).",
	["Las ondas al caminar o nadar en el agua."] = "As ondulações ao andar ou nadar na água.",
	["Las orillas de la pantalla un poco más oscuras."] = "As bordas da tela um pouco mais escuras.",
	["Las pestañas toman la letra y los colores del estilo; la elegida lleva la línea de acento. En Clásico WoW quedan las del juego."] = "As abas assumem a fonte e as cores do estilo; a escolhida leva a linha de destaque. No WoW Clássico ficam as do jogo.",
	["Las piedras de afilar y los contrapesos que haces le sirven a guerreros y pícaros: siempre tienen compradores."] = "As pedras de amolar e os contrapesos que você faz servem para guerreiros e ladinos: sempre têm compradores.",
	["Las piedras de salud que creas le salvan la vida a todo tu grupo."] = "As pedras de vida que você cria salvam a vida do seu grupo inteiro.",
	["Las placas de nombre de los enemigos."] = "As placas de nome dos inimigos.",
	["Las plantas de herboristería."] = "As plantas de herborismo.",
	["Las pociones de vida y maná siempre se venden: toda mazmorra las pide."] = "As poções de vida e mana sempre vendem: toda masmorra pede.",
	["Las primeras misiones de un humano en Villanorte van de kóbolds, bandidos Defias... y lobos. No todos somos buenos, ¿eh?"] = "As primeiras missões de um humano em Vila Norte falam de kobolds, bandidos Défias... e lobos. Nem todos nós somos bonzinhos, viu?",
	["Las profesiones de fabricación dan retos del Legado al llegar a 150, 225 y 300."] = "As profissões de fabricação dão desafios do Legado ao chegar a 150, 225 e 300.",
	["Las profesiones de recolección dan oro desde el nivel 1. ¡Hierbas o minería!"] = "As profissões de coleta dão ouro desde o nível 1. Herborismo ou mineração!",
	["Las que Lya ya te dijo sus tres veces. Con «Volver a mostrarlos» salen otra vez."] = "As que a Lya já disse três vezes para você. Com «Mostrá-los de novo» elas aparecem outra vez.",
