	["Lo mejor que sacaste: %s."] = "O melhor que você conseguiu: %s.",
	["Lo mejor: %s."] = "O melhor: %s.",
	["Lo menos que espera Lya entre un consejo y otro. Lo importante no espera."] = "O mínimo que a Lya espera entre uma dica e outra. O importante não espera.",
	["Lo menos que espera Lya entre una historia y otra. Nunca en combate ni en mazmorras."] = "O mínimo que a Lya espera entre uma história e outra. Nunca em combate nem em masmorras.",
	["Lo más cerca"] = "O mais perto",
	["Lo más cerca de ti"] = "O mais perto de você",
	["Lo más gastado va al %d %%. Te llevo con quien repare."] = "Sua peça mais gasta está em %d %%. Levo você até quem conserta.",
	["Lo más ligero: para equipos modestos o para subir los FPS en peleas grandes."] = "O mais leve: para computadores modestos ou para subir o FPS em lutas grandes.",
	["Lo más parecido"] = "O mais parecido",
	["Lo más útil para este momento, en grande: tu siguiente paso, lo urgente y tu camino a un par de clics."] = "O mais útil para agora, em grande: seu próximo passo, o urgente e seu caminho a poucos cliques.",
	["Lo nuevo de esta versión"] = "Novidades desta versão",
	["Lo nuevo de esta versión, en pocas palabras."] = "O que há de novo nesta versão, em poucas palavras.",
	["Lo nuevo en Alfa %s"] = "Novidades do Alfa %s",
	["Lo nuevo en Alfa 1.0"] = "Novidades do Alfa 1.0",
	["Lo olimos, lo seguimos y cayó. ¡Así caza la manada!"] = "Farejamos, seguimos e ele caiu. É assim que a matilha caça!",
	["Lo pequeño que hace el juego más cómodo: el minimapa, el chat y las barras con el estilo de Alfa, marcos, cuadro de información, probador, cámara y sonidos; y en sus pestañas, viajes, invitaciones, comerciantes y más."] = "O pequeno que deixa o jogo mais confortável: o minimapa, o chat e as barras no estilo do Alfa, molduras, dica de ferramenta, provador, câmera e sons; e nas abas, viagens, convites, comerciantes e mais.",
	["Lo pequeño que hace el juego más cómodo: misiones, vuelos, minimapa, chat y barras con el estilo de Alfa, marcos, cuadro de información, probador, cámara y sonidos."] = "As pequenas coisas que deixam o jogo mais confortável: missões, voos, minimapa, chat e barras no estilo do Alfa, quadros, dica de interface, provador, câmera e sons.",
	["Lo pescado en esta sesión"] = "O que você pescou nesta sessão",
	["Lo piden estas misiones"] = "Pedido nestas missões",
	["Lo pones al empezar a pelear."] = "Você ativa ao começar a luta.",
	["Lo primero que puedes soltar: %s (%s)."] = "A primeira coisa que você pode largar: %s (%s).",
	["Lo que Alfa acepta, rechaza o comparte sola. Mantén presionado Mayús para decidir tú en el momento."] = "O que o Alfa aceita, recusa ou compartilha sozinho. Segure Shift para decidir você mesmo na hora.",
	["Lo que Lya nota"] = "O que a Lya nota",
	["Lo que Lya sabe de aquí"] = "O que a Lya sabe deste lugar",
	["Lo que buscas en la Enciclopedia"] = "O que você busca na Enciclopédia",
	["Lo que comparte alguien de tu grupo con Alfa llega a tus marcadores, con su nombre, y te avisa para seguirlo."] = "O que alguém do seu grupo compartilha com o Alfa chega aos seus marcadores, com o nome da pessoa, e avisa você para seguir.",
	["Lo que conoce Alfa"] = "O que o Alfa conhece",
	["Lo que cuentan las misiones que vas tomando"] = "O que contam as missões que você vai pegando",
	["Lo que da"] = "O que dá",
	["Lo que dice el diario de monturas"] = "O que o diário de montarias diz",
	["Lo que el menú del juego no enseña, a tu gusto"] = "O que o menu do jogo não mostra, do seu jeito",
	["Lo que elegiste al configurarlo: aceptar y entregar misiones, vender lo gris, reparar, tomar vuelos... Lo cambias cuando quieras."] = "O que você escolheu ao configurar: aceitar e entregar missões, vender o cinza, consertar, pegar voos... Mude quando quiser.",
	["Lo que encuentras en la manada"] = "O que você encontra na matilha",
	["Lo que este personaje lleva en las mazmorras: se guarda solo al vencer jefes y recoger botín."] = "O que este personagem já fez nas masmorras: salvo sozinho ao derrotar chefes e pegar saque.",
	["Lo que ganaste la última vez que jugaste con este personaje."] = "O que você ganhou na última vez que jogou com este personagem.",
	["Lo que gastan tus hechizos"] = "O que seus feitiços gastam",
	["Lo que hay dentro"] = "O que tem dentro",
	["Lo que llevas"] = "O que você leva",
	["Lo que llevas pescado: %s."] = "O que você já pescou: %s.",
	["Lo que me sirve"] = "O que me serve",
	["Lo que menos vale: %s"] = "O que vale menos: %s",
	["Lo que más conviene ahora"] = "O que mais vale a pena agora",
	["Lo que más rinde cerca de ti"] = "O que mais rende perto de você",
	["Lo que obtuviste en esta sesión"] = "O que você obteve nesta sessão",
	["Lo que pescaste"] = "O que você pescou",
	["Lo que pide %s antes, en orden."] = "O que %s pede antes, em ordem.",
	["Lo que quieras contarle al desarrollador de Alfa."] = "O que você quiser contar ao desenvolvedor do Alfa.",
	["Lo que quieras; la marcas tú cuando la hagas."] = "O que você quiser; você a marca quando fizer.",
	["Lo que sabe de Alfa"] = "O que ela sabe do Alfa",
	["Lo que sacas en %s: %s."] = "O que você pesca em %s: %s.",
	["Lo que se pesca aquí"] = "O que se pesca aqui",
	["Lo que se queda la subasta de cada venta. Suele ser 5 % en la de tu facción y 15 % en la neutral. Es un estimado."] = "O que o leilão fica de cada venda. Costuma ser 5% no da sua facção e 15% no neutro. É uma estimativa.",
	["Lo que sigue en tu build no está en tu árbol"] = "O próximo da sua build não está na sua árvore",
	["Lo que sigue pide este nivel: hasta entonces, la guía no te manda allá."] = "O que vem depois pede este nível: até lá, o guia não manda você para lá.",
	["Lo que sugiere Alfa"] = "O que o Alfa sugere",
	["Lo que te ha contado"] = "O que ela já contou para você",
	["Lo que te ofrece Lya (su botón)"] = "O que a Lya oferece (o botão dela)",
	["Lo que te pasa a ti: curación recibida, esquivas, recursos. Puede necesitar /reload la primera vez."] = "O que acontece com você: cura recebida, esquivas, recursos. Pode precisar de /reload na primeira vez.",
	["Lo que te piden"] = "O que pedem a você",
	["Lo que tenía ya está hecho, omitido o fuera de tu registro. Ármalo otra vez con las misiones que tienes ahora."] = "O que ele tinha está feito, pulado ou fora do seu registro. Monte de novo com as missões que você tem agora.",
	["Lo que trajo la última versión de Alfa, contado corto."] = "O que a última versão do Alfa trouxe, resumido.",
	["Lo que tu build necesita de tu equipo y dónde conseguirlo."] = "O que sua build precisa do seu equipamento e onde conseguir.",
	["Lo que tu clase se pone antes de pelear está activo."] = "O que sua classe ativa antes de lutar está ativo.",
	["Lo que tu profesión de recolección junta mejor."] = "O que sua profissão de coleta junta melhor.",
	["Lo que vale"] = "Quanto vale",
	["Lo que ya tienes en el banco"] = "O que você já tem no banco",
	["Lo recolectaste %d veces"] = "Você coletou %d vezes",
	["Lo recolectaste 1 vez"] = "Você coletou 1 vez",
	["Lo revisa el desarrollador de Alfa. En ese canal nadie más ve tu mensaje. Si aún no estás en el Discord, entra con la invitación de arriba."] = "O desenvolvedor do Alfa lê. Nesse canal ninguém mais vê sua mensagem. Se você ainda não está no Discord, entre com o convite acima.",
	["Lo sigues"] = "Você segue",
	["Lo sigues: el rastreador te muestra la meta de ahora y la flecha va a cada lugar."] = "Você segue: o rastreador mostra a meta atual e a seta vai a cada lugar.",
	["Lo siguiente"] = "O próximo",
	["Lo siguiente para ti"] = "O próximo para você",
	["Lo sueltan"] = "Quem deixa cair",
	["Lo último que consultaste"] = "O que você consultou por último",
	["Lo último que te dije"] = "O que eu te disse por último",
	["Lobo"] = "Lobo",
	["Lobos conectados"] = "Lobos conectados",
	["Logrado el %s"] = "Conquistado em %s",
	["Logrados"] = "Conquistados",
	["Logro de pesca: %s"] = "Conquista de pesca: %s",
	["Logros"] = "Conquistas",
	["Logros de pesca"] = "Conquistas de pesca",
	["Lord Kazzak, un demonio enorme, ronda las Tierras Devastadas; en el Clásico es un jefe de mundo para bandas."] = "Lorde Kazzak, um demônio enorme, ronda a Barreira do Inferno; no Clássico é um chefe mundial para raides.",
	["Lord Xavius, el consejero de Azshara, convenció a los Altonato de abrirle la puerta a Sargeras. Cuando murió, Sargeras lo trajo de vuelta como el primer sátiro."] = "Lorde Xavius, o conselheiro de Azshara, convenceu os Bem-nascidos a abrir a porta para Sargeras. Quando morreu, Sargeras o trouxe de volta como o primeiro sátiro.",
	["Los Altonato eran la nobleza élfica que vivía para la magia del Pozo. Su reina, Azshara, era tan bella que su pueblo la adoraba."] = "Os Bem-nascidos eram a nobreza élfica que vivia para a magia da Nascente. Sua rainha, Azshara, era tão bela que seu povo a adorava.",
	["Los Amani pelearon contra los altos elfos durante miles de años. Su capital, Zul'Aman, está en los bosques cerca de Quel'Thalas."] = "Os Amani lutaram contra os altos elfos durante milhares de anos. Sua capital, Zul'Aman, fica nas florestas perto de Quel'Thalas.",
	["Los Barbabronce ganaron la Guerra de los Tres Martillos, y por eso Forjaz es suya."] = "Os Barbabronze venceram a Guerra dos Três Martelos, e por isso Altaforja é deles.",
	["Los Claros de Tirisfal guardan las ruinas de Lordaeron, el reino de Arthas. Bajo su antigua capital, los Renegados levantaron Entrañas."] = "As Clareiras de Tirisfal guardam as ruínas de Lordaeron, o reino de Arthas. Sob sua antiga capital, os Renegados ergueram a Cidade Baixa.",
	["Los Defias usan cosechadores mecánicos que trabajan solos en los campos... y no les gustan las visitas."] = "Os Défias usam ceifadores mecânicos que trabalham sozinhos nos campos... e não gostam de visitas.",
	["Los Furiarena de Zul'Farrak son trols del desierto, primos lejanos de los Lanza Negra."] = "Os Fúria-da-areia de Zul'Farrak são trolls do deserto, primos distantes dos Lançanegra.",
	["Los Gurubashi llamaron a Hakkar, el Desollador de Almas. Cuando vieron lo que hacía, las demás tribus se unieron para echarlo."] = "Os Gurubashi chamaram Hakkar, o Esfolador de Almas. Quando viram o que ele fazia, as outras tribos se uniram para expulsá-lo.",
	["Los Hierro Negro invocaron a Ragnaros sin querer al final de la Guerra de los Tres Martillos, y desde entonces son sus esclavos."] = "Os Ferro Negro invocaram Ragnaros sem querer no fim da Guerra dos Três Martelos, e desde então são seus escravos.",
	["Los Hierro Negro también excavan en Uldaman, buscando lo mismo que los enanos de Forjaz."] = "Os Ferro Negro também escavam em Uldaman, procurando o mesmo que os anões de Altaforja.",
	["Los Lanza Negra suelen terminar sus frases con un «mon». ¡Se pega, mon!"] = "Os Lançanegra costumam terminar as frases com um «mon». Pega, mon!",
	["Los PNJ dejan de hablar al saludarte o al darte misiones. También calla las voces de error."] = "Os PNJs param de falar ao cumprimentar você ou ao dar missões. Também silencia as vozes de erro.",
	["Los Perdidos del pantano son draenei que llegaron de Draenor y quedaron cambiados para siempre."] = "Os Perdidos do pântano são draeneis que vieram de Draenor e ficaram mudados para sempre.",
	["Los Páramos de Poniente eran el granero de Ventormenta; hoy muchas de sus granjas están en manos de la Hermandad Defias."] = "O Cerro Oeste era o celeiro de Ventobravo; hoje muitas de suas fazendas estão nas mãos da Irmandade Défias.",
	["Los Renegados aguantan bajo el agua mucho más que los vivos. ¡No necesitan respirar tanto!"] = "Os Renegados aguentam embaixo d'água muito mais que os vivos. Não precisam respirar tanto!",
	["Los Renegados entraron a la Horda gracias a los tauren, que esperaban encontrarles una cura. Muchos orcos aún no se fían de ellos."] = "Os Renegados entraram na Horda graças aos taurens, que esperavam encontrar uma cura para eles. Muitos orcs ainda não confiam neles.",
	["Los Renegados hicieron de Rémol, un viejo pueblo humano, su primera parada en Tirisfal."] = "Os Renegados fizeram de Brill, um velho povoado humano, sua primeira parada em Tirisfal.",
	["Los Renegados nuevos despiertan en Camposanto, en Tirisfal, como no-muertos libres del Rey Exánime."] = "Os Renegados novos despertam em Sino da Morte, em Tirisfal, como mortos-vivos livres do Lich Rei.",
	["Los Renegados pueden comerse cadáveres para recuperar vida. Yo prefiero las salchichas, gracias."] = "Os Renegados podem comer cadáveres para recuperar vida. Eu prefiro salsichas, obrigada.",
	["Los Renegados recuerdan quiénes fueron en vida, y eso pesa más que cualquier herida."] = "Os Renegados se lembram de quem foram em vida, e isso pesa mais que qualquer ferida.",
	["Los Renegados son no-muertos que recuperaron su voluntad cuando el poder del Rey Exánime se debilitó."] = "Os Renegados são mortos-vivos que recuperaram o livre-arbítrio quando o poder do Lich Rei enfraqueceu.",
	["Los Tótem Siniestro son tauren que no quieren a la Horda; su jefa Magatha vive en la misma Cima del Trueno."] = "Os Temível Totem são taurens que não gostam da Horda; sua chefe Magatha vive no próprio Penhasco do Trovão.",
	["Los ajustes de los recordatorios están en la búsqueda de la ventana de Alfa."] = "As opções dos lembretes estão na busca da janela do Alfa.",
	["Los altos elfos pelearon con la Alianza en la Segunda Guerra por una vieja deuda de sangre con el linaje de Thoradin."] = "Os altos elfos lutaram com a Aliança na Segunda Guerra por uma velha dívida de sangue com a linhagem de Thoradin.",
	["Los altos elfos que sobrevivieron a la Plaga empezaron a llamarse elfos de sangre, en honor a los suyos caídos. Kael'thas los guía."] = "Os altos elfos que sobreviveram ao Flagelo passaram a se chamar elfos sangrentos, em honra aos seus caídos. Kael'thas os guia.",
	["Los antídotos que haces curan venenos. ¡En las arañas de Vallefresno se agradecen!"] = "Os antídotos que você faz curam venenos. Com as aranhas do Vale Gris, vêm bem a calhar!",
	["Los aqir eran un imperio antiguo de insectos que peleó contra los trols. De ellos vienen los qiraji de Ahn'Qiraj y los nerubianos del norte."] = "Os aqir eram um antigo império de insetos que lutou contra os trolls. Deles vêm os qiraji de Ahn'Qiraj e os nerubianos do norte.",
	["Los avisos de viaje hablan como la manada: «La manada viaja», el lobo en el aro y una huellita que camina mientras llega tu barco."] = "Os avisos de viagem falam como a matilha: “A matilha viaja”, o lobo no anel e uma pegada que caminha enquanto seu barco chega.",
	["Los avisos pequeños de Alfa los dice Lya en su globo, con su botón, en vez de salir arriba. Si está oculta o en combate, salen como siempre."] = "Os avisos pequenos do Alfa a Lya fala no balão dela, com o botão, em vez de aparecer em cima. Se ela estiver escondida ou em combate, aparecem como sempre.",
	["Los ayudantes de los enemigos."] = "Os ajudantes dos inimigos.",
	["Los botones de otros addons alrededor del minimapa (también el de Alfa) solo aparecen al pasar el ratón por encima."] = "Os botões de outros addons em volta do minimapa (o do Alfa também) só aparecem ao passar o mouse por cima.",
	["Los cebos suben tu habilidad de pesca un rato: úsalos en aguas difíciles."] = "As iscas aumentam sua habilidade de pesca por um tempo: use-as em águas difíceis.",
	["Los cementerios del Ocaso están llenos de no-muertos levantados por nigromantes que se esconden en el bosque."] = "Os cemitérios da Floresta do Crepúsculo estão cheios de mortos-vivos erguidos por necromantes escondidos na floresta.",
	["Los centauros dicen descender de Zaetar, hijo del semidiós Cenarius, y de Theradras, la princesa de la tierra. Pelean entre sus clanes casi tanto como contra los demás."] = "Os centauros dizem descender de Zaetar, filho do semideus Cenarius, e de Theradras, a princesa da terra. Seus clãs brigam entre si quase tanto quanto contra os outros.",
	["Los cinco Aspectos Dragón recibieron su poder de los titanes: Alexstrasza la vida, Ysera el sueño, Nozdormu el tiempo, Malygos la magia y Neltharion la tierra."] = "Os cinco Aspectos Dragônicos receberam seu poder dos titãs: Alexstrasza a vida, Ysera o sonho, Nozdormu o tempo, Malygos a magia e Neltharion a terra.",
	["Los clanes Gelkis y Magram de Desolace pelean entre sí, y ambos buscan aliados entre los aventureros."] = "Os clãs Gelkis e Magram de Desolação brigam entre si, e ambos buscam aliados entre os aventureiros.",
	["Los clanes orcos tienen historias distintas: Lobo Gélido, Grito de Guerra, Roca Negra, Faucedraco... cada uno con su orgullo."] = "Os clãs orcs têm histórias diferentes: Lobo do Gelo, Brado Guerreiro, Rocha Negra, Presa do Dragão... cada um com seu orgulho.",
	["Los cruzados escarlata vienen en grupos y algunos curan: interrumpan a los que curan."] = "Os cruzados escarlates vêm em grupos e alguns curam: interrompam os que curam.",
	["Los críticos hacen el doble de daño y al guerrero le dan más ira."] = "Os críticos causam o dobro de dano e dão mais raiva ao guerreiro.",
	["Los cuatro dragones verdes de la pesadilla, Ysondre, Lethon, Emeriss y Taerar, aparecen junto a los grandes árboles del Sueño."] = "Os quatro dragões verdes do pesadelo, Ysondre, Lethon, Emeriss e Taerar, aparecem junto às grandes árvores do Sonho.",
	["Los cuatro señores elementales son Ragnaros del fuego, Al'Akir del aire, Therazane de la tierra y Neptulon del agua."] = "Os quatro senhores elementais são Ragnaros do fogo, Al'Akir do ar, Therazane da terra e Neptulon da água.",
	["Los cultistas del Martillo Crepuscular usan piedras de viento para invocar a sus señores; con su disfraz, tú también puedes."] = "Os cultistas do Martelo do Crepúsculo usam pedras de vento para invocar seus senhores; com o disfarce deles, você também pode.",
	["Los datos de Alfa no cargaron (%s)."] = "Os dados do Alfa não carregaram (%s).",
	["Los datos de Alfa no traen botín propio de sus jefes."] = "Os dados do Alfa não trazem saque próprio dos chefes dela.",
	["Los datos de las mazmorras no están cargados."] = "Os dados das masmorras não estão carregados.",
	["Los datos de las mazmorras se cargan fuera de combate. Esta página se llena sola al terminar la pelea."] = "Os dados das masmorras carregam fora de combate. Esta página se preenche sozinha quando a luta terminar.",
	["Los datos del mundo (Codex) no están disponibles: faltan los bancos, las misiones y de dónde sale cada cosa."] = "Os dados do mundo (Codex) não estão disponíveis: faltam os cardumes, as missões e a origem de cada coisa.",
	["Los datos del mundo de Alfa están apagados: activa «Alfa Codex» en la lista de addons."] = "Os dados do mundo do Alfa estão desativados: ative «Alfa Codex» na lista de addons.",
	["Los datos son del medidor oficial del juego: tú, tu grupo o banda y sus mascotas."] = "Os dados são do medidor oficial do jogo: você, seu grupo ou raide e os mascotes.",
	["Los dioses antiguos son seres de antes de los titanes, encerrados bajo la tierra de Azeroth. C'Thun y Yogg-Saron susurran a quien quiera escuchar."] = "Os Deuses Antigos são seres de antes dos titãs, presos sob a terra de Azeroth. C'Thun e Yogg-Saron sussurram para quem quiser ouvir.",
	["Los dioses antiguos susurran en la mente de los mortales; muchos cultos, como el Martillo Crepuscular, nacieron de escucharlos."] = "Os Deuses Antigos sussurram na mente dos mortais; muitos cultos, como o Martelo do Crepúsculo, nasceram de escutá-los.",
	["Los dos"] = "Os dois",
	["Los dos bandos"] = "As duas facções",
	["Los dracoleones son las monturas voladoras de la Horda; los grifos, las de la Alianza; y los hipogrifos, las de los elfos de la noche."] = "As serpes são as montarias voadoras da Horda; os grifos, as da Aliança; e os hipogrifos, as dos elfos noturnos.",
	["Los dracónidos negros rondan la entrada de la guarida de Onyxia, al sur del marjal."] = "Draconatos negros rondam a entrada do covil de Onyxia, no sul do pântano.",
	["Los dracónidos son los soldados de los dragones; los negros sirven a Nefarian en la Montaña Roca Negra."] = "Os draconatos são os soldados dos dragões; os negros servem a Nefarian na Montanha Rocha Negra.",
	["Los draenei huyeron de su mundo, Argus, con el profeta Velen. Su nombre quiere decir «los exiliados»."] = "Os draeneis fugiram do seu mundo, Argus, com o profeta Velen. O nome deles quer dizer «os exilados».",
	["Los dragones cromáticos, con escamas de todos los colores, son experimentos de Nefarian. Su obra más temida es Chromaggus."] = "Os dragões cromáticos, com escamas de todas as cores, são experimentos de Nefarian. Sua obra mais temida é Chromaggus.",
	["Los dragones negros se disfrazan de humanos para engañar: Onyxia es Lady Katrana Prestor en Ventormenta, y Nefarian se hace llamar Lord Victor Nefarius."] = "Os dragões negros se disfarçam de humanos para enganar: Onyxia é Lady Katrana Prestor em Ventobravo, e Nefarian se faz chamar Lorde Victor Nefarius.",
	["Los dragones verdes siguen vigilando el templo hundido para que nadie vuelva a llamar a Hakkar."] = "Os dragões verdes continuam vigiando o templo afundado para que ninguém volte a chamar Hakkar.",
	["Los elementales de fuego de La Garganta de Fuego y del Cráter de Un'Goro sueltan materiales de fuego que piden muchas profesiones."] = "Os elementais de fogo da Garganta Abrasadora e da Cratera Un'Goro soltam materiais de fogo que muitas profissões pedem.",
	["Los elementales de fuego y las arañas de lava son los vecinos de siempre de La Garganta de Fuego."] = "Elementais de fogo e aranhas de lava são os vizinhos de sempre da Garganta Abrasadora.",
	["Los elfos de la noche fueron inmortales gracias a Nordrassil, hasta que lo sacrificaron para vencer a Archimonde en el Monte Hyjal."] = "Os elfos noturnos foram imortais graças a Nordrassil, até que a sacrificaram para vencer Archimonde no Monte Hyjal.",
	["Los elfos de la noche montan sables, grandes felinos. No es por nada, pero un lobo es más simpático."] = "Os elfos noturnos montam sabres, grandes felinos. Não é por nada, mas um lobo é mais simpático.",
	["Los elfos de la noche nuevos empiezan en la Cañada Umbría, en Teldrassil, entre arañas y fuegos fatuos."] = "Os elfos noturnos novos começam no Vale Sombrio, em Teldrassil, entre aranhas e fogos-fátuos.",
	["Los elfos de la noche pueden fundirse con las sombras cuando se quedan quietos."] = "Os elfos noturnos podem se fundir às sombras quando ficam parados.",
	["Los elfos de la noche se unieron a la Alianza después de la Tercera Guerra."] = "Os elfos noturnos se uniram à Aliança depois da Terceira Guerra.",
	["Los enanos Hierro Negro tomaron Dun Modr, al norte de Los Humedales, y desde ahí molestan a quien cruce el puente."] = "Os anões Ferro Negro tomaram Dun Modr, ao norte do Pantanal, e de lá incomodam quem cruza a ponte.",
	["Los enanos creen descender de los terráneos de piedra de los titanes, y por eso la Liga de Expedicionarios excava sin parar."] = "Os anões acreditam descender dos terranos de pedra dos titãs, e por isso a Liga dos Exploradores escava sem parar.",
	["Los enanos de Forjaz pelean contra los Hierro Negro en Los Humedales y en las Tierras Inhóspitas."] = "Os anões de Altaforja lutam contra os Ferro Negro no Pantanal e nos Ermos.",
	["Los enanos nuevos empiezan en un valle helado de Dun Morogh, peleando contra trols de las nieves y troggs."] = "Os anões novos começam num vale gelado de Dun Morogh, lutando contra trolls do gelo e troggs.",
	["Los encantadores también hacen varitas: los magos, sacerdotes y brujos te lo agradecerán."] = "Os encantadores também fazem varinhas: magos, sacerdotes e bruxos vão agradecer.",
	["Los enemigos de alrededor pegan menos."] = "Os inimigos ao redor batem menos.",
	["Los enemigos de tus misiones marcados sobre su placa de nombre y los objetos de misión brillando en tus bolsas."] = "Os inimigos das suas missões marcados sobre a placa de nome e os itens de missão brilhando nas suas bolsas.",
	["Los enemigos lanzan radiación y veneno: lleven pociones de vida."] = "Os inimigos lançam radiação e veneno: levem poções de vida.",
	["Los enemigos más débiles, que el juego marca con un signo de menos."] = "Os inimigos mais fracos, que o jogo marca com um sinal de menos.",
	["Los espíritus de las elfas caídas que la Plaga esclaviza se vuelven banshees. Sylvanas es la más famosa de todas."] = "Os espíritos das elfas caídas que o Flagelo escraviza viram banshees. Sylvanas é a mais famosa de todas.",
	["Los fragmentos de alma se ganan drenando el alma del enemigo justo cuando muere."] = "Os fragmentos de alma se ganham drenando a alma do inimigo bem na hora em que ele morre.",
	["Los frascos del Clásico duran dos horas y aguantan aunque mueras: por eso las bandas los piden tanto."] = "Os frascos do Clássico duram duas horas e continuam mesmo se você morrer: por isso as raides pedem tanto.",
	["Los frascos más poderosos llevan Loto negro, la hierba más rara de Azeroth."] = "Os frascos mais poderosos levam Lótus Negro, a erva mais rara de Azeroth.",
	["Los fuegos artificiales también son ingeniería. ¡Uno para festejar cada nivel!"] = "Os fogos de artifício também são engenharia. Um para comemorar cada nível!",
	["Los fuegos fatuos son espíritus de elfos de la noche que siguen cuidando el bosque después de morir."] = "Os fogos-fátuos são espíritos de elfos noturnos que continuam cuidando da floresta depois de morrer.",
	["Los furbolgs Fauces de Madera son de los pocos que no se han corrompido; sus túneles llevan a Cuna del Invierno y al Claro de la Luna."] = "Os furbolgues Presamadeira estão entre os poucos que não se corromperam; seus túneis levam a Hibérnia e à Clareira da Lua.",
	["Los furbolgs de Costa Oscura se están corrompiendo, y los elfos de Auberdine no saben bien por qué."] = "Os furbolgues da Costa Negra estão se corrompendo, e os elfos de Auberdine não sabem bem por quê.",
	["Los furbolgs eran un pueblo pacífico de hombres oso, pero la corrupción de los demonios enloqueció a muchas de sus tribus."] = "Os furbolgues eram um povo pacífico de homens-urso, mas a corrupção dos demônios enlouqueceu muitas das suas tribos.",
	["Los geomantes lanzan fuego y ponen tótems: interrúmpanlos y rompan los tótems."] = "Os geomantes lançam fogo e colocam totens: interrompam-nos e quebrem os totens.",
	["Los gnomos empiezan con los enanos en Dun Morogh: Gnomeregan está perdida y tu gente vive refugiada en Forjaz."] = "Os gnomos começam com os anões em Dun Morogh: Gnomeregan está perdida e seu povo vive refugiado em Altaforja.",
	["Los gnomos inventaron el Tranvía Subterráneo que une Forjaz con Ventormenta."] = "Os gnomos inventaram o Metrô Correfundo que liga Altaforja a Ventobravo.",
	["Los gnomos que se quedaron en Gnomeregan quedaron dañados por la radiación; algunos perdieron la razón."] = "Os gnomos que ficaram em Gnomeregan foram afetados pela radiação; alguns perderam a razão.",
	["Los goblins de la fundición tienen ayudantes cerca: miren alrededor antes de atacar."] = "Os goblins da fundição têm ajudantes por perto: olhem em volta antes de atacar.",
	["Los goblins vienen de la isla de Kezan, y su gran ciudad es Minahonda. Le son más leales al oro que a cualquier bando."] = "Os goblins vêm da ilha de Kezan, e sua grande cidade é Subminas. São mais leais ao ouro que a qualquer facção.",
	["Los grandes árboles que hablan en Darnassus y Vallefresno son Ancestros, guardianes del bosque."] = "As grandes árvores que falam em Darnassus e no Vale Gris são Antigos, guardiões da floresta.",
	["Los grifos (o dragones) a los lados de la barra principal."] = "Os grifos (ou dragões) nas laterais da barra principal.",
	["Los grifos (o dragones) a los lados de la barra principal. «Del color del estilo» necesita el estilo de las barras; «Ocultos» funciona siempre."] = "Os grifos (ou serpes) dos lados da barra principal. «Da cor do estilo» precisa do estilo das barras; «Ocultos» funciona sempre.",
	["Los gules, las abominaciones y las gárgolas son los soldados más comunes de la Plaga. Las abominaciones se cosen con partes de muchos cadáveres."] = "Os carniçais, as abominações e as gárgulas são os soldados mais comuns do Flagelo. As abominações são costuradas com partes de muitos cadáveres.",
	["Los herreros hacen llaves que abren cofres y cajas cerradas. ¡Útil y divertido!"] = "Os ferreiros fazem chaves que abrem baús e caixas trancadas. Útil e divertido!",
	["Los humanos fueron los primeros en aprender magia de los altos elfos, allá en las Guerras Trol."] = "Os humanos foram os primeiros a aprender magia com os altos elfos, lá nas Guerras Trolls.",
	["Los infernales son demonios que la Legión arroja desde el cielo como meteoritos."] = "Os infernais são demônios que a Legião atira do céu como meteoritos.",
	["Los ingenieros pueden fabricar mascotas mecánicas, como una ardilla."] = "Os engenheiros podem fabricar mascotes mecânicos, como um esquilo.",
	["Los instructores y vendedores de pesca se ven en el mapa y el minimapa."] = "Os instrutores e vendedores de pesca aparecem no mapa e no minimapa.",
	["Los jefes opcionales y raros se descubren al terminar la mazmorra."] = "Os chefes opcionais e raros são descobertos quando você termina a masmorra.",
	["Los jefes se descubren al vencerlos: su nombre y su botín quedan ocultos hasta entonces. Sus consejos siempre se pueden ver."] = "Os chefes são descobertos quando você os derrota: o nome e o saque ficam ocultos até lá. As dicas sempre podem ser vistas.",
	["Los kits de armadura que haces le sirven a todo el mundo: siempre hay quien los compre."] = "Os kits de armadura que você faz servem para todo mundo: sempre tem quem compre.",
	["Los kodos son los compañeros de viaje de los tauren, y en Desolace está su cementerio."] = "Os kodos são os companheiros de viagem dos taurens, e em Desolação fica o cemitério deles.",
	["Los kóbolds de las minas de Elwynn cuidan sus velas como un tesoro: bajo tierra, la luz lo es todo."] = "Os kobolds das minas de Elwynn cuidam das velas como um tesouro: debaixo da terra, a luz é tudo.",
	["Los lobos aprenden Aullido furioso, que sube el daño de tu grupo. ¡Ya ves, los lobos somos lo máximo!"] = "Os lobos aprendem Uivo Furioso, que aumenta o dano do seu grupo. Viu? Nós, lobos, somos demais!",
	["Los lobos de tu zona saben dónde estás. Te aviso quién viene."] = "Os lobos da sua zona sabem onde você está. Eu aviso quem vem.",
	["Los lobos que se dejan ver en el mapa. Un clic en su marca y la flecha te lleva."] = "Os lobos que se deixam ver no mapa. Um clique na marca deles e a seta leva você.",
	["Los lobos que usan Alfa y se dejan ver en el mapa, y tu grupo, que ves ahora."] = "Os lobos que usam o Alfa e se deixam ver no mapa, e seu grupo, que você vê agora.",
	["Los logros de la manada: se ganan pescando, cocinando lo que pescas y explorando aguas nuevas. Cada uno se anuncia una sola vez."] = "As conquistas da matilha: ganhas pescando, cozinhando o que você pesca e explorando águas novas. Cada uma é anunciada uma só vez.",
	["Los lugares que pides ver en el mapa desde la Enciclopedia."] = "Os lugares que você pede para ver no mapa a partir da Enciclopédia.",
	["Los maestros de vuelo de tu facción y los neutrales: verdes si ya los conoces, ámbar con «?» si te falta descubrirlos. Clic: seguirlo con la flecha."] = "Os mestres de voo da sua facção e os neutros: verdes se você já os conhece, âmbar com «?» se ainda falta descobri-los. Clique: segui-lo com a seta.",
	["Los magos de Dalaran forman el Kirin Tor, su consejo de sabios."] = "Os magos de Dalaran formam o Kirin Tor, seu conselho de sábios.",
	["Los marcos de Curación están apagados"] = "Os quadros de Cura estão desativados",
	["Los marcos se mueven fuera de combate."] = "Os quadros são movidos fora de combate.",
	["Los marcos, fondos, botones y letras del propio juego, con títulos en oro."] = "Os quadros, fundos, botões e fontes do próprio jogo, com títulos em dourado.",
	["Los mismos marcadores de misiones en el minimapa."] = "Os mesmos marcadores de missões no minimapa.",
	["Los múrlocs hablan con gorgoteos y burbujas: ese «mrglglgl» es su idioma de verdad."] = "Os murlocs falam com gorgolejos e bolhas: esse «mrglglgl» é a língua deles de verdade.",
	["Los nagas y sátiros lanzan escarcha y rayos: interrumpan a los lanzadores primero."] = "Os nagas e sátiros lançam gelo e raios: interrompam os lançadores primeiro.",
	["Los nerubianos, arañas gigantes de Rasganorte, pelearon contra el Rey Exánime y perdieron; muchos hoy le sirven."] = "Os nerubianos, aranhas gigantes de Nortúndria, lutaram contra o Lich Rei e perderam; muitos hoje o servem.",
	["Los no-muertos de la Plaga no sienten miedo ni cansancio, y por eso es tan difícil detenerlos."] = "Os mortos-vivos do Flagelo não sentem medo nem cansaço, e por isso é tão difícil detê-los.",
	["Los nodos de la zona que miras, con su nombre, nivel y cuántas veces los recolectaste al pasar el ratón. Clic en uno: la flecha te lleva."] = "Os pontos da zona que você está vendo; passe o mouse para ver nome, nível e quantas vezes você coletou. Clique num deles: a seta leva você.",
	["Los nodos que se pisarían en pantalla van en un solo pin con su cantidad. Al acercar el mapa se separan."] = "Os pontos que ficariam sobrepostos na tela viram um só marcador com a quantidade. Ao aproximar o mapa, eles se separam.",
	["Los nodos que tienes cerca. El punto del rastreo del juego dice si ahora hay algo ahí."] = "Os pontos que estão perto de você. O ponto do rastreamento do jogo diz se agora há algo ali.",
	["Los nodos que trae Alfa. Sin esto solo ves los que tú descubriste."] = "Os pontos que vêm com o Alfa. Sem isto, você só vê os que descobriu.",
	["Los números de las habilidades de tu mascota."] = "Os números das habilidades do seu ajudante.",
	["Los números de lo que curas encima de quien recibe."] = "Os números da sua cura sobre quem a recebe.",
	["Los números de los golpes de tu mascota."] = "Os números dos golpes do seu ajudante.",
	["Los números de tu daño encima de quien golpeas."] = "Os números do seu dano sobre quem você acerta.",
	["Los oasis de Los Baldíos se están secando y llenando de bestias raras: los Druidas del Colmillo, que salieron de las Cuevas de los Lamentos, los corrompen."] = "Os oásis dos Sertões estão secando e se enchendo de feras estranhas: os Druidas da Presa, que saíram da Caverna Ululante, os corrompem.",
	["Los objetos se juntan al final de tus bolsas en lugar de al principio."] = "Os itens se juntam no fim das bolsas em vez de no começo.",
	["Los orcos Faucedraco siguen en Los Humedales, aunque ya sin la Reina Dragón."] = "Os orcs Presa do Dragão continuam no Pantanal, embora já sem a Rainha Dragão.",
	["Los orcos Roca Negra de Rend se adueñaron de la cumbre de la montaña y la llaman su hogar."] = "Os orcs Rocha Negra de Rend se apossaram do cume da montanha e o chamam de lar.",
	["Los orcos Roca Negra ocupan una vieja fortaleza humana al este de las montañas."] = "Os orcs Rocha Negra ocupam uma velha fortaleza humana a leste das montanhas.",
	["Los orcos llegaron de Draenor corrompidos por la sangre de Mannoroth. Thrall los sacó de los campos de internamiento y fundó la nueva Horda."] = "Os orcs vieram de Draenor corrompidos pelo sangue de Mannoroth. Thrall os tirou dos campos de internamento e fundou a nova Horda.",
	["Los orcos nuevos empiezan en el Valle de los Retos, en Durotar, donde prueban su valor."] = "Os orcs novos começam no Vale das Provações, em Durotar, onde provam seu valor.",
	["Los orcos vienen de Draenor, un mundo que hoy está roto y se llama Terrallende."] = "Os orcs vêm de Draenor, um mundo que hoje está partido e se chama Terralém.",
	["Los otros %d puntos del plan llegan con tus próximos niveles."] = "Os outros %d pontos do plano chegam com os seus próximos níveis.",
	["Los peleteros hacen carcajes y bolsas de munición para los cazadores."] = "Os coureiros fazem aljavas e bolsas de munição para os caçadores.",
	["Los portales a pie que puedes usar, con a dónde llevan."] = "Os portais a pé que você pode usar, com o destino de cada um.",
	["Los precios cambian: después de estos días Alfa te recuerda escanear otra vez."] = "Os preços mudam: depois desses dias, o Alfa lembra você de escanear de novo.",
	["Los primeros caballeros de la muerte los creó Gul'dan: cuerpos de caballeros humanos caídos con almas de brujos orcos."] = "Os primeiros cavaleiros da morte foram criados por Gul'dan: corpos de cavaleiros humanos caídos com almas de bruxos orcs.",
	["Los puntos de ruta que ponen otros addons, y el comando /way, apuntan la flecha de Alfa. Un addon que espere los ajustes de otro addon de puntos de ruta puede no funcionar con esto encendido."] = "Os pontos de rota que outros addons definem, e o comando /way, apontam a seta do Alfa. Um addon que espere as opções de outro addon de pontos de rota pode não funcionar com isso ativado.",
	["Los puntos de vuelo y de viaje ya se ven en el mapa."] = "Os pontos de voo e de viagem já aparecem no mapa.",
	["Los puntos que ganas en la cuenta también llenan el registro del Legado: premios de aspecto, sin ventaja en el juego. Al salir Forever son un rifle de réplica de Forjaz (juguete), la cría de oso espectral (mascota), el tabardo del oso espectral y las riendas del oso espectral (montura)."] = "Os pontos que você ganha na conta também enchem a trilha de recompensas do Legado: prêmios de aparência, sem vantagem no jogo. No lançamento do Forever são uma réplica de rifle de ar de Altaforja (brinquedo), o filhote de urso espectral (mascote), o tabardo do urso espectral e as rédeas do urso espectral (montaria).",
	["Los puntos que ganas también llenan el registro del Legado, con premios de aspecto como la cría de oso espectral."] = "Os pontos que você ganha também enchem a trilha de recompensas do Legado, com prêmios de aparência como o filhote de urso espectral.",
	["Los raros están apagados (página Descubrir)."] = "Os raros estão desativados (página Descoberta).",
	["Los raros que cayeron hace poco"] = "Raros abatidos há pouco",
	["Los raros también en el minimapa."] = "Os raros também no minimapa.",
	["Los recolectaste %d veces en total"] = "Você coletou %d vezes no total",
	["Los sacerdotes Atal'ai siguieron adorando a Hakkar en secreto. Los desterraron, y levantaron su templo en el Pantano de las Penas."] = "Os sacerdotes Atal'ai continuaram adorando Hakkar em segredo. Foram desterrados e ergueram seu templo no Pântano das Mágoas.",
	["Los servicios también en el minimapa."] = "Os serviços também no minimapa.",
	["Los señores del terror, como Mal'Ganis, Balnazzar y Varimathras, eran los carceleros que la Legión le puso al Rey Exánime."] = "Os senhores do medo, como Mal'Ganis, Balnazzar e Varimathras, eram os carcereiros que a Legião pôs sobre o Lich Rei.",
	["Los señores elementales servían a los dioses antiguos. Cuando los titanes encerraron a esos dioses, desterraron a los elementales a sus propios planos."] = "Os senhores elementais serviam aos Deuses Antigos. Quando os titãs prenderam esses deuses, desterraram os elementais para seus próprios planos.",
	["Los sumos sacerdotes de Zul'Gurub tomaron el poder de los loa animales: el murciélago, la serpiente, la araña, la pantera y el tigre."] = "Os sumos sacerdotes de Zul'Gurub tomaram o poder dos loa animais: o morcego, a serpente, a aranha, a pantera e o tigre.",
	["Los sátiros de Azshara sueltan tela vil, muy buscada por los sastres."] = "Os sátiros de Azshara soltam tecido vil, muito procurado pelos alfaiates.",
	["Los talentos confirmados no se quitan gratis: revisa la lista antes de aceptar."] = "Talentos confirmados não saem de graça: confira a lista antes de aceitar.",
	["Los talentos que siguen en el plan no están en tu árbol o no se pueden tomar todavía. Ponlos a mano en la ventana de talentos del juego o elige otro build."] = "Os próximos talentos do plano não estão na sua árvore ou ainda não podem ser pegos. Coloque-os à mão na janela de talentos do jogo ou escolha outra build.",
	["Los tauren Tótem Siniestro tienen campamentos en Las Mil Agujas, y no son nada amigables."] = "Os taurens Temível Totem têm acampamentos em Mil Agulhas, e não são nada amigáveis.",
	["Los tauren ayudaron a los Renegados a entrar a la Horda, con la esperanza de encontrarles una cura."] = "Os taurens ajudaram os Renegados a entrar na Horda, na esperança de encontrar uma cura para eles.",
	["Los tauren de Viento Libre viven en lo alto de Las Mil Agujas, a salvo de los centauros."] = "Os taurens de Ventolivre vivem no alto de Mil Agulhas, a salvo dos centauros.",
	["Los tauren de Viento Libre viven en lo alto de las agujas, unidas por puentes colgantes, a salvo de los centauros de abajo."] = "Os taurens de Ventolivre vivem no alto das agulhas, unidas por pontes suspensas, a salvo dos centauros lá embaixo.",
	["Los tauren honran a la Madre Tierra. Dicen que el sol y la luna son sus ojos: An'she y Mu'sha."] = "Os taurens honram a Mãe Terra. Dizem que o sol e a lua são os olhos dela: An'she e Mu'sha.",
	["Los tauren llaman An'she al sol y Mu'sha a la luna: los ojos de la Madre Tierra."] = "Os taurens chamam o sol de An'she e a lua de Mu'sha: os olhos da Mãe Terra.",
	["Los tauren nuevos empiezan en el Campamento Narache, en Mulgore."] = "Os taurens novos começam no Acampamento Narache, em Mulgore.",
	["Los tauren vivían como nómadas, acosados por los centauros, hasta que Cairne Pezuña de Sangre se alió con Thrall. Con la ayuda de la Horda encontraron su hogar en Mulgore."] = "Os taurens viviam como nômades, acossados pelos centauros, até que Cairne Casco Sangrento se aliou a Thrall. Com a ajuda da Horda encontraram seu lar em Mulgore.",
	["Los tesoros también en el minimapa."] = "Os tesouros também no minimapa.",
	["Los titanes dejaron guardianes de piedra y metal en Azeroth. En Uldaman todavía hay uno despierto: Archaedas."] = "Os titãs deixaram guardiões de pedra e metal em Azeroth. Em Uldaman ainda há um desperto: Archaedas.",
	["Los titanes le dieron forma a Azeroth y dejaron guardianes y ciudades, como Uldaman, para cuidar su obra."] = "Os titãs deram forma a Azeroth e deixaram guardiões e cidades, como Uldaman, para cuidar da sua obra.",
	["Los titanes son seres colosales que recorren el cosmos poniendo orden en los mundos. Los más famosos forman el Panteón, que guiaba Aman'Thul."] = "Os titãs são seres colossais que percorrem o cosmos pondo ordem nos mundos. Os mais famosos formam o Panteão, que Aman'Thul guiava.",
	["Los titanes usaron este cráter como un jardín de pruebas para la vida; por eso hay dinosaurios y plantas gigantes."] = "Os titãs usaram esta cratera como um jardim de testes para a vida; por isso há dinossauros e plantas gigantes.",
	["Los troggs huyen cuando tienen poca vida y traen amigos: deténganlos antes de que escapen."] = "Os troggs fogem quando estão com pouca vida e trazem amigos: segurem-nos antes que escapem.",
	["Los troggs invadieron Gnomeregan, y los gnomos inundaron su propia ciudad de radiación al intentar sacarlos. Fue idea del mekigeniero Termochufe."] = "Os troggs invadiram Gnomeregan, e os gnomos inundaram a própria cidade de radiação ao tentar expulsá-los. Foi ideia do mecangenheiro Termaplugue.",
	["Los troggs salieron de las profundidades de Uldaman. Todo indica que son una creación antigua de los titanes que salió mal."] = "Os troggs saíram das profundezas de Uldaman. Tudo indica que são uma criação antiga dos titãs que deu errado.",
	["Los trols Lanza Negra conocieron a Thrall en las islas donde naufragó su flota rumbo a Kalimdor. Su líder Sen'jin murió ahí, y desde entonces los guía su hijo Vol'jin."] = "Os trolls Lançanegra conheceram Thrall nas ilhas onde sua frota naufragou a caminho de Kalimdor. Seu líder Sen'jin morreu ali, e desde então seu filho Vol'jin os guia.",
	["Los trols Lanza Negra empiezan con los orcos, en el Valle de los Retos de Durotar."] = "Os trolls Lançanegra começam com os orcs, no Vale das Provações de Durotar.",
	["Los trols adoran a espíritus llamados loa. Hakkar es uno de ellos, y de los más peligrosos."] = "Os trolls adoram espíritos chamados loa. Hakkar é um deles, e dos mais perigosos.",
	["Los trols de estas tierras descienden de los Amani, el antiguo imperio de los trols del bosque. En Jintha'Alor siguen levantando sus altares."] = "Os trolls destas terras descendem dos Amani, o antigo império dos trolls da floresta. Em Jintha'Alor continuam erguendo seus altares.",
	["Los vendedores de suministros de pesca tienen cañas, lombrices y baratijas."] = "Os vendedores de suprimentos de pesca têm varas, minhocas e bugigangas.",
	["Los worgen son hombres lobo de origen misterioso. Arugal los trajo a Lordaeron. ¡No me confundas con ellos, eh!"] = "Os worgens são lobisomens de origem misteriosa. Arugal os trouxe para Lordaeron. Não vá me confundir com eles, hein!",
	["Los zepelines salen de las torres junto a Orgrimmar hacia Entrañas y hacia Grom'gol, en la Vega de Tuercespina."] = "Os zepelins saem das torres perto de Orgrimmar para a Cidade Baixa e para Grom'gol, na Selva do Espinhaço.",
	["Los árboles del Legado son tres: Profesiones, Aventura y Recursos. Al salir Forever, cada personaje gasta hasta 16 puntos."] = "As árvores do Legado são três: Profissões, Aventura e Engenhosidade. No lançamento do Forever, cada personagem gasta até 16 pontos.",
	["Los íconos, los nombres y tu flecha se mueven pegados al mapa al hacer zoom o arrastrar: ya no brincan un píxel."] = "Os ícones, os nomes e a sua seta ficam grudados no mapa ao dar zoom ou arrastar: não pulam mais um pixel.",
	["Los últimos Altonato de Kalimdor siguen en La Masacre: se llaman Shen'dralar y cuidan su vieja biblioteca."] = "Os últimos Bem-nascidos de Kalimdor continuam em Gládio Cruel: se chamam Shen'dralar e cuidam da sua velha biblioteca.",
	["Los últimos puntos."] = "Os últimos pontos.",
	["Lothar cayó ante Orgrim Martillo Maldito al pie de la Montaña Roca Negra. Turalyon tomó su lugar y ganó la Segunda Guerra."] = "Lothar caiu diante de Orgrim Martelo da Perdição ao pé da Montanha Rocha Negra. Turalyon tomou seu lugar e venceu a Segunda Guerra.",
	["Luego cópialo con Ctrl+C."] = "Depois copie com Ctrl+C.",
	["Lugar"] = "Posição",
