	["Lya"] = "Lya",
	["Lya ahora es una loba negra de cuerpo completo, con 39 cuadros de animación: se sienta, corre, se busca la cola, bosteza y duerme enroscada."] = "A Lya agora é uma loba negra de corpo inteiro, com 39 quadros de animação: ela senta, corre, persegue o rabo, boceja e dorme enroladinha.",
	["Lya aprende"] = "A Lya aprende",
	["Lya apunta aquí tus pasos grandes: tu primera mazmorra, tus niveles, tu primera montura y más."] = "A Lya anota aqui seus grandes passos: sua primeira masmorra, seus níveis, sua primeira montaria e mais.",
	["Lya apunta tus pasos grandes (tu primera mazmorra, tus niveles, tu primera montura...) y festeja cada página nueva."] = "A Lya anota seus grandes passos (sua primeira masmorra, seus níveis, sua primeira montaria...) e comemora cada página nova.",
	["Lya cuenta historias"] = "A Lya conta histórias",
	["Lya de cuerpo completo"] = "Lya de corpo inteiro",
	["Lya descansa. La llamas con /alfa lya o /alfa ayuda cuando quieras."] = "A Lya descansa. Chame-a com /alfa lya ou /alfa ayuda quando quiser.",
	["Lya en las mazmorras"] = "A Lya nas masmorras",
	["Lya en las mazmorras, con ánimo, su salchicha y su despedida; y te enseña Alfa en 5 pasos."] = "A Lya nas masmorras, com humor, a salsicha dela e a despedida; e ela te mostra o Alfa em 5 passos.",
	["Lya en tu pantalla"] = "Lya na sua tela",
	["Lya encontró un tesoro"] = "Lya encontrou um tesouro",
	["Lya es quien olfatea los raros y los tesoros: su tarjeta trae «Ir de caza», «Su ficha» y «Seleccionarlo»."] = "É a Lya quem fareja raros e tesouros: o cartão dela traz “Ir caçar”, “A ficha dele” e “Selecionar”.",
	["Lya está calladita"] = "A Lya está quietinha",
	["Lya está descansando"] = "A Lya está descansando",
	["Lya fue una gran perrita: noble, leal y siempre al lado de los suyos, la gordita consentida de la casa. Alfa la recuerda así, como la loba que cuida a la manada y nunca deja a nadie atrás."] = "A Lya foi uma cachorrinha incrível: nobre, leal e sempre ao lado dos seus, a gordinha mimada da casa. O Alfa se lembra dela assim, como a loba que cuida da matilha e nunca deixa ninguém para trás.",
	["Lya guarda la historia de cada misión que tomas, aunque la aceptes sin leerla. Tú sigue la flecha: ella se acuerda de todo."] = "A Lya guarda a história de cada missão que você pega, mesmo que aceite sem ler. Você segue a seta: ela se lembra de tudo.",
	["Lya lleva tu historia, aprende qué consejos ya no quieres y te avisa de tus oficios."] = "A Lya guarda sua história, aprende quais dicas você não quer mais e te avisa das suas profissões.",
	["Lya olfateó un raro"] = "Lya farejou um raro",
	["Lya platica mucho más: lore de Warcraft, datos de cada zona, de tu raza, tu clase y tus profesiones, y consejos de eventos y de farmeo. ¡Y le encantan las salchichas!"] = "A Lya conversa muito mais: lore de Warcraft, curiosidades de cada zona, da sua raça, sua classe e suas profissões, e dicas de eventos e de farm. E ela adora salsichas!",
	["Lya recuerda lo que te dijo, tiene una tecla para su botón y te cuenta tu semana de caza y tu mejor día."] = "A Lya lembra o que te disse, tem uma tecla para o botão dela e conta sua semana de caçada e seu melhor dia.",
	["Lya se fue a descansar. Vuelve con /alfa lya."] = "A Lya foi descansar. Traga-a de volta com /alfa lya.",
	["Lya se queda calladita una hora. Aquí sigue, cuidándote."] = "A Lya fica quietinha por uma hora. Ela continua aqui, cuidando de você.",
	["Lya se queda en tu pantalla: consejos cortos, historias y atajos a todo Alfa."] = "A Lya fica na sua tela: dicas curtas, histórias e atalhos para todo o Alfa.",
	["Lya te acompaña"] = "A Lya acompanha você",
	["Lya te cuenta"] = "A Lya te conta",
	["Lya te cuenta cuánto tardaron, cuántas veces caíste y lo mejor que sacaste."] = "A Lya te conta quanto tempo levou, quantas vezes você caiu e o melhor que você conseguiu.",
	["Lya te dice los avisos"] = "A Lya fala os avisos",
	["Lya te enseña la ventana de Alfa en 5 pasos"] = "A Lya te mostra a janela do Alfa em 5 passos",
	["Lya te enseña la ventana de Alfa en 5 pasos. También con /alfa recorrido."] = "A Lya te mostra a janela do Alfa em 5 passos. Também com /alfa recorrido.",
	["Lya te espera"] = "A Lya espera por você",
	["Lya te guía, un asistente más sencillo y las guaridas"] = "A Lya guia você, uma configuração mais simples e as tocas",
	["Lya te lo dice todo"] = "A Lya te diz tudo",
