	["Para mí"] = "Para mim",
	["Para no chocar con él, Alfa no reemplaza tus bolsas mientras esté activo. Igual puedes abrir la ventana de Alfa desde aquí."] = "Para não conflitar com ele, o Alfa não substitui suas bolsas enquanto ele estiver ativo. Mesmo assim, você pode abrir a janela do Alfa por aqui.",
	["Para no moverla sin querer. Sin bloquear, arrástrala a donde quieras."] = "Para não movê-la sem querer. Destravada, arraste-a para onde quiser.",
	["Para no ver dos veces a tu grupo. Se cambia fuera de combate."] = "Para não ver seu grupo duas vezes. Muda fora de combate.",
	["Para proponer una cita, deja que la manada te vea en el mapa."] = "Para propor um encontro, deixe a matilha te ver no mapa.",
