	["Sanación"] = "Cura",
	["Sanador"] = "Curador",
	["Sangrado fuerte desde el nivel 13; lo necesitas para Heridas profundas."] = "Sangramento forte desde o nível 13; você precisa dele para Feridas Profundas.",
	["Sangrado fuerte; abre Heridas profundas."] = "Sangramento forte; abre Feridas Profundas.",
	["Sangre fría: tu siguiente remate es crítico seguro."] = "Sangue Frio: seu próximo finalizador é crítico garantido.",
	["Sapphiron, el dragón de escarcha de Naxxramas, fue un dragón azul antes de que la Plaga lo levantara."] = "Sapphiron, o dragão de gelo de Naxxramas, foi um dragão azul antes de o Flagelo erguê-lo.",
	["Sargeras fue el gran campeón del Panteón. De tanto pelear contra demonios concluyó que la creación no tenía remedio, y fundó la Legión Ardiente."] = "Sargeras foi o grande campeão do Panteão. De tanto lutar contra demônios, concluiu que a criação não tinha jeito, e fundou a Legião Ardente.",
	["Sastrería"] = "Alfaiataria",
	["Sastrería hace tu ropa con lo que cae en mazmorras, y Encantamiento deshace lo que no usas y mejora tu equipo."] = "A Alfaiataria faz suas roupas com o que cai nas masmorras, e o Encantamento desfaz o que você não usa e melhora seu equipamento.",
	["Sastrería y Encantamiento: tu equipo siempre al día."] = "Alfaiataria e Encantamento: seu equipamento sempre em dia.",
	["Scholomance, en la isla de Caer Darrow, es la escuela donde la Plaga enseña nigromancia. Antes fue el hogar de la familia Barov."] = "Scholomance, na ilha de Caer Darrow, é a escola onde o Flagelo ensina necromancia. Antes foi o lar da família Barov.",
	["Se abandona con «Abandonar marcadas», que pide confirmación."] = "Abandona-se com “Abandonar marcadas”, que pede confirmação.",
	["Se abre a nivel %d: te faltan %d niveles. Mientras, sigue tu ruta."] = "Abre no nível %d: faltam %d níveis. Enquanto isso, siga sua rota.",
	["Se abre al salir de combate."] = "Abre quando o combate terminar.",
	["Se abre al terminar %s."] = "Abre ao terminar %s.",
	["Se abren con la B. Elige la vista (todo junto, por categorías o por bolsa), busca por nombre o nivel y arrastra tus bolsas en su barra para cambiarlas."] = "Abrem com B. Escolha a visão (tudo junto, por categoria ou por bolsa), busque por nome ou nível e arraste suas bolsas na barra delas para trocá-las.",
	["Se acabaron los textos cortados con «…» en Hoy, La Jauría, Buscar cerca y la Enciclopedia."] = "Acabaram os textos cortados com «…» em Hoje, La Jauría, Buscar perto e na Enciclopédia.",
	["Se acabó el aviso «Alfa_Builds se ha bloqueado…»: la ventana de talentos, el clic para lanzar y el Legado ahora los abre el juego, y tus hechizos se lanzan sin problema desde el libro."] = "Acabou o aviso «Alfa_Builds foi bloqueado…»: a janela de talentos, o clique para lançar e o Legado agora são abertos pelo jogo, e seus feitiços são lançados sem problema pelo grimório.",
	["Se acabó tu XP descansada"] = "Sua XP de descanso acabou",
	["Se acelera a sí mismo y lanza rayos: interrúmpelo."] = "Ele acelera a si mesmo e lança raios: interrompa.",
	["Se acelera a sí mismo: interrúmpelo si puedes."] = "Ele acelera a si mesmo: interrompa se puder.",
	["Se activó Claridad: tu siguiente hechizo es gratis."] = "Clarividência ativada: seu próximo feitiço é grátis.",
	["Se activó Claridad: tus Misiles arcanos salen gratis."] = "Clarividência ativada: seus Mísseis Arcanos saem grátis.",
	["Se activó Trance de las Sombras: tu Descarga de las Sombras es instantánea."] = "Transe Sombrio ativado: sua Seta Sombria é instantânea.",
	["Se agregó el sonido %d a tu lista."] = "O som %d foi adicionado à sua lista.",
	["Se aplica al salir de combate."] = "Aplica-se ao sair de combate.",
	["Se aprende con %s"] = "Aprendido com %s",
	["Se borra el progreso de mazmorras de este personaje. No se puede deshacer."] = "O progresso de masmorras deste personagem será apagado. Não dá para desfazer.",
	["Se borran las sesiones guardadas de este personaje. La sesión de ahora sigue contando."] = "As sessões salvas deste personagem serão apagadas. A sessão atual continua contando.",
	["Se borran las sesiones, las zonas y los objetos de este personaje. No se puede deshacer."] = "As sessões, as zonas e os itens deste personagem serão apagados. Não dá para desfazer.",
	["Se borran los %d marcadores de todos tus personajes. No se puede deshacer."] = "Os %d marcadores de todos os seus personagens serão apagados. Não dá para desfazer.",
	["Se borran los jefes vencidos, las veces completada y el botín anotado de %s para este personaje."] = "Os chefes derrotados, as vezes concluídas e o saque anotado de %s serão apagados para este personagem.",
	["Se borran los precios guardados de la subasta de este reino y facción. Tus recetas se quedan."] = "Os preços de leilão salvos deste reino e facção serão apagados. Suas receitas continuam.",
	["Se borran todas las peleas guardadas, también en la ventana del medidor del juego."] = "Todas as lutas salvas são apagadas, inclusive na janela do medidor do jogo.",
	["Se borran tus sesiones, tu diario, tus logros y tus metas de este personaje. Tu habilidad de pesca no cambia."] = "Apagam-se suas sessões, seu diário, suas conquistas e suas metas deste personagem. Sua habilidade de pesca não muda.",
	["Se carga al salir de combate"] = "Carrega ao sair de combate",
	["Se cerró el buzón antes de terminar."] = "A caixa de correio fechou antes de terminar.",
	["Se cerró la subasta antes de recibir los precios. Vuelve a intentarlo después."] = "O leilão fechou antes de receber os preços. Tente de novo depois.",
	["Se cerró la ventana de clic para lanzar de Blizzard. Vuelve a pulsar «Abrir clic para lanzar» para abrirla."] = "A janela de clique para lançar da Blizzard foi fechada. Clique de novo em «Abrir clique para lançar» para abri-la.",
	["Se cumple al llegar a ese nivel."] = "Cumprida ao chegar a esse nível.",
	["Se cura a sí mismo: interrumpe su curación."] = "Ele se cura: interrompa a cura dele.",
	["Se cura comiendo: mátenlo rápido."] = "Ele se cura comendo: matem-no rápido.",
	["Se cura: interrúmpelo."] = "Ele se cura: interrompa.",
	["Se descubren todos los jefes de %s, como si la hubieras terminado. Si te equivocas, puedes olvidar tu progreso aquí."] = "Todos os chefes de %s são revelados, como se você a tivesse terminado. Se foi um engano, você pode esquecer seu progresso aqui.",
	["Se detuvo al cerrar el banco: guardaste %d y faltaron %d."] = "Parou quando o banco fechou: você guardou %d e faltaram %d.",
	["Se detuvo al entrar en combate: guardaste %d y faltaron %d."] = "Parou ao entrar em combate: você guardou %d e faltaram %d.",
	["Se enfurece al final: guarden su mejor daño."] = "Ele se enfurece no fim: guardem o melhor dano.",
	["Se enfurece con poca vida: termínenlo rápido."] = "Ele se enfurece com pouca vida: acabem com ele rápido.",
	["Se enfurece y pega más fuerte con el tiempo: mátenlo rápido."] = "Ele se enfurece e bate mais forte com o tempo: matem-no rápido.",
