	["Se pueden conseguir"] = "Obteníveis",
	["Se pusieron %d ajustes. Algunas cosas se ven completas al recargar."] = "%d opções aplicadas. Algumas coisas aparecem completas ao recarregar.",
	["Se pusieron %d de %d opciones"] = "Foram aplicadas %d de %d opções",
	["Se queda en el modo limpio."] = "Continua no modo limpo.",
	["Se quita de tu lista. Si lo necesitas otra vez, vuelve a importar su cadena."] = "Ela sai da sua lista. Se precisar de novo, importe o código dela outra vez.",
	["Se quitan los nodos que anotaste al recolectar y cuántas veces los recolectaste. La base incluida se queda. No se puede deshacer."] = "São removidos os pontos que você anotou ao coletar e quantas vezes coletou. A base incluída fica. Não dá para desfazer.",
	["Se quitó el sonido %d de tu lista."] = "O som %d foi tirado da sua lista.",
	["Se saltan (no están en tu árbol): %s."] = "Pulados (não estão na sua árvore): %s.",
	["Se teletransporta a las orillas de la sala: si peleas cuerpo a cuerpo, síguelo."] = "Ele se teleporta para as bordas da sala: se você luta corpo a corpo, vá atrás dele.",
	["Se toma dentro de la mazmorra: ahí la verás."] = "Pega-se dentro da masmorra: você a verá lá.",
	["Se ve después de reiniciar los gráficos."] = "Aparece depois de reiniciar os gráficos.",
