	["Sepia"] = "Sépia",
	["Servicio"] = "Serviço",
	["Servicios"] = "Serviços",
	["Servicios en el minimapa"] = "Serviços no minimapa",
	["Será una mejora más adelante"] = "Será uma melhoria mais adiante",
	["Sesiones anteriores"] = "Sessões anteriores",
	["Sesiones que guarda el diario"] = "Sessões que o diário guarda",
	["Sesiones, diario, logros y metas de este personaje. No se puede deshacer."] = "Sessões, diário, conquistas e metas deste personagem. Não dá para desfazer.",
	["Sesión de pesca nueva."] = "Nova sessão de pesca.",
	["Señalar"] = "Apontar",
	["Señor de las aguas"] = "Senhor das águas",
	["Si Toxic, el fundador de La Jauría, anda cerca, Alfa te avisa para que lo saludes."] = "Se Toxic, o fundador de La Jauría, estiver por perto, o Alfa te avisa para você cumprimentá-lo.",
	["Si aguantas bien, usa Golpe heroico con la ira sobrante para más amenaza."] = "Se estiver aguentando bem, use Golpe Heroico com a raiva que sobra para ter mais ameaça.",
	["Si algo sale mal, tu habilidad para desaparecer te saca de la pelea. Úsala antes de que sea tarde."] = "Se algo der errado, sua habilidade de sumir tira você da luta. Use antes que seja tarde.",
	["Si alguien de la manada te pasa uno, impórtalo y Alfa te guía con él punto por punto."] = "Se alguém da matilha passar uma para você, importe e o Alfa guia você com ela ponto por ponto.",
	["Si alguien huye, puede traer a más presos: deténganlo con un ataque que lo frene."] = "Se alguém fugir, pode trazer mais presos: segurem-no com um ataque que deixe lento.",
	["Si alguna vez ves salchichas en una posada, guárdame una… o dos."] = "Se um dia vir salsichas numa estalagem, guarda uma pra mim… ou duas.",
	["Si bajas por el Gran Elevador, verás por qué se llama así: cientos de agujas de roca."] = "Se você descer pelo Grande Elevador, vai ver por que se chama assim: centenas de agulhas de rocha.",
	["Si casi todo lo que vas a entregar está en el pueblo de tu piedra y estás lejos, Lya te lo dice."] = "Se quase tudo o que você vai entregar está na cidade da sua pedra e você está longe, a Lya te avisa.",
	["Si cierras tres veces el mismo tipo de consejo, Lya te pregunta si ya no quieres que te lo diga."] = "Se você fechar três vezes o mesmo tipo de dica, a Lya pergunta se você não quer mais que ela diga.",
	["Si en estas fechas ves calabazas en las posadas, es Halloween: los posaderos te dan dulces con truco o trato, y a veces un disfraz."] = "Se nesta época você vir abóboras nas estalagens, é a Noturnália: os estalajadeiros dão doces no doces ou travessuras, e às vezes uma fantasia.",
	["Si en estas fechas ves faroles y fuegos artificiales, es el Festival Lunar: visita a los Ancestros por el mundo, que cada uno te da una moneda."] = "Se nesta época você vir lanternas e fogos de artifício, é o Festival da Lua: visite os Anciões pelo mundo, cada um dá uma moeda.",
	["Si en febrero las ciudades huelen a perfume, es «Amor en el aire»: la gente reparte regalos y hasta los guardias reciben detalles."] = "Se em fevereiro as cidades têm cheiro de perfume, é «O Amor Está no Ar»: as pessoas distribuem presentes e até os guardas ganham mimos.",
	["Si encuentras un hueso, es mío. ¿Trato hecho?"] = "Se achar um osso, é meu. Combinado?",
	["Si eres desollador, las zonas llenas de bestias, como raptores, kodos o felinos, te dan cuero sin parar."] = "Se você é esfolador, as zonas cheias de feras, como raptores, kodos ou felinos, dão couro sem parar.",
	["Si está fuera de tu alcance, su marco se ve más tenue."] = "Se estiver fora do seu alcance, o quadro dele fica mais apagado.",
	["Si fabricas para otros, cobra justo: la gente vuelve y te recomienda."] = "Se você fabrica para os outros, cobre um preço justo: as pessoas voltam e recomendam você.",
	["Si hoy cuesta, mañana sale. Aquí sigo contigo."] = "Se hoje está difícil, amanhã sai. Continuo aqui com você.",
	["Si juegas sin grupo, la ventana se esconde."] = "Se você joga sem grupo, a janela se esconde.",
	["Si la abandonas, pierdes la cadena: después sigue “%s”."] = "Se abandoná-la, você perde a sequência: depois vem «%s».",
	["Si la pelea va mal, desvanécete y vuelve a empezar."] = "Se a luta for mal, suma e comece de novo.",
	["Si la recompensa tiene varias opciones, eliges tú."] = "Se a recompensa tiver várias opções, você escolhe.",
	["Si la terminas"] = "Se você concluir",
	["Si la vida baja de la mitad y el sanador no llega, usa Último recurso."] = "Se a vida baixar da metade e o curador não der conta, use Last Stand.",
	["Si le dices «Ya no» a un consejo, sale aquí para que puedas devolverlo cuando quieras."] = "Se você disser \"Não mais\" a uma dica, ela aparece aqui para você trazê-la de volta quando quiser.",
	["Si le haces el gesto de gallina a una gallina de granja muchas veces, a veces te pide ayuda... y la historia termina en mascota."] = "Se você fizer o gesto de galinha para uma galinha de fazenda muitas vezes, às vezes ela pede ajuda... e a história termina em mascote.",
	["Si llega a 0 % se rompe y deja de darte sus estadísticas. Repara cuanto antes con un herrero o un vendedor que repare."] = "Em 0 % sua peça quebra e deixa de dar os atributos. Repare o quanto antes com um ferreiro ou um mercador que faça reparos.",
	["Si llegas a exaltado con otra raza de tu bando, te venden sus monturas. ¡Un kodo para un orco o un sable de la noche para un humano!"] = "Se chegar a exaltado com outra raça da sua facção, ela vende as montarias dela. Um kodo para um orc ou um sabre-noturno para um humano!",
	["Si llevas puesto el abalorio del Alba Argenta, los no-muertos de las Tierras de la Peste sueltan piedras que cambias por reputación y fichas."] = "Se você estiver com o berloque da Aurora Argêntea, os mortos-vivos das Terras Pestilentas soltam pedras que se trocam por reputação e fichas.",
	["Si lo que te dan mejora tu equipo, te lo pones al salir de combate."] = "Se o que você recebe melhora seu equipamento, você o equipa ao sair de combate.",
	["Si moviste los avisos y ya no los encuentras."] = "Se você moveu os avisos e não os encontra mais.",
	["Si mueres seguido, cambia al estilo Tranquilo."] = "Se você morrer com frequência, mude para o estilo Tranquilo.",
	["Si necesitas silencio, con clic derecho me callas un rato."] = "Se precisar de silêncio, com o botão direito você me faz calar um pouco.",
	["Si no eres druida, al Claro de la Luna se llega por los túneles de los Fauces de Madera, desde Frondavil."] = "Se você não é druida, chega-se à Clareira da Lua pelos túneis dos Presamadeira, a partir da Selva Maleva.",
	["Si no tienes ninguna abierta, abre la recomendada para tu nivel."] = "Se você não tiver nenhum aberto, abre o recomendado para o seu nível.",
	["Si nos perdemos en %s, tú lees el mapa y yo sigo el rastro."] = "Se a gente se perder em %s, você lê o mapa e eu sigo o rastro.",
	["Si peleas de lejos, quédate lejos de ella."] = "Se você luta à distância, fique longe dela.",
	["Si quieres matar más rápido en solitario, cambia a Armas cuando tengas oro para reiniciar."] = "Se quiser matar mais rápido sozinho, mude para Armas quando tiver ouro para redefinir.",
	["Si quieres, tu personaje aparece en el mapa del juego de los lobos que usan Alfa, y ellos en el tuyo: quién anda cerca, dónde y, con un clic, la flecha te lleva. Solo es el lugar de tu personaje dentro de WoW, nunca tu ubicación real. Tu grupo se ve siempre."] = "Se você quiser, seu personagem aparece no mapa do jogo dos lobos que usam o Alfa, e eles no seu: quem anda por perto, onde e, com um clique, a seta leva você. É só o lugar do seu personagem dentro do WoW, nunca sua localização real. Seu grupo aparece sempre.",
	["Si sigues el consejo"] = "Se você seguir o conselho",
	["Si sigues la cadena del mariscal Windsor, en Ventormenta destaparás quién es en realidad Lady Prestor."] = "Se você seguir a série do marechal Windsor, em Ventobravo vai desmascarar quem é Lady Prestor de verdade.",
	["Si sigues la historia del Templo Sumergido, en el pantano te espera Itharius, un dragón verde."] = "Se seguir a história do Templo Submerso, Itharius, um dragão verde, espera por você no pântano.",
	["Si sigues los consejos"] = "Se você seguir os conselhos",
	["Si sigues los consejos ganas %s"] = "Seguindo as dicas, você ganha %s",
	["Si te alcanzan, usa tus golpes cuerpo a cuerpo y aléjate otra vez."] = "Se alcançarem você, use seus golpes corpo a corpo e afaste-se de novo.",
	["Si te baja mucho la vida, cambia a actitud defensiva: tu ira no se pierde."] = "Se a sua vida baixar muito, mude para a Postura Defensiva: sua raiva não se perde.",
	["Si te invitan a su grupo, acepta con el botón del juego: el juego te pasa a su guarida al rato."] = "Se convidarem você para o grupo, aceite com o botão do jogo: o jogo leva você à toca deles pouco depois.",
	["Si te pegan mientras te vendas, se corta: aléjate un poco antes de usarla."] = "Se baterem em você enquanto se enfaixa, interrompe: afaste-se um pouco antes de usar a atadura.",
	["Si te quedas sin lanzar"] = "Se você parar de lançar",
	["Si te sobra un pedacito de carne, aquí hay una panza que lo recibe con gusto."] = "Se sobrar um pedacinho de carne, aqui tem uma barriga que recebe com todo o prazer.",
	["Si tienes poco tiempo, si no tienes con quién jugar o quién te ayude, puedes apoyarte en Alfa y en Lya en tu travesía."] = "Se você tem pouco tempo, ou não tem com quem jogar nem quem ajude, pode contar com o Alfa e a Lya na sua jornada.",
	["Si tu caña no tiene cebo, tu tecla pone el mejor que tengas (o el que prefieras) antes de lanzar."] = "Se sua vara não tiver isca, sua tecla coloca a melhor que você tiver (ou a preferida) antes de lançar.",
	["Si tu objetivo es un jugador, su fondo toma el color de su clase en lugar del de su reacción."] = "Se o seu alvo for um jogador, o fundo fica com a cor da classe dele em vez da cor de reação.",
	["Si tu rango lo permite, la hermandad paga y tu dinero pone el resto."] = "Se sua patente permitir, a guilda paga e o seu dinheiro cobre o resto.",
	["Si tú o tus personajes pueden"] = "Se você ou seus personagens puderem",
	["Si un día ganamos mucho oro, yo ya sé en qué gastarlo: salchichas."] = "Se um dia a gente ganhar muito ouro, eu já sei em que gastar: salsichas.",
	["Si un enemigo te persigue, no corras: acércate al tanque."] = "Se um inimigo perseguir você, não corra: chegue perto do tanque.",
	["Si un enemigo viene hacia ti, llévalo hacia el tanque: no corras lejos."] = "Se um inimigo vier atrás de você, leve-o até o tanque: não corra para longe.",
	["Si un lugar está lleno de jugadores farmeando lo mismo, cámbiate de zona: te rinde más."] = "Se um lugar estiver cheio de jogadores farmando a mesma coisa, mude de zona: rende mais.",
	["Si un monstruo esquiva, usa Abrumar enseguida (Alfa te avisa)."] = "Se um monstro se esquivar, use Sobrepujar na hora (o Alfa avisa).",
	["Si una misión se pone difícil, pide ayuda en el chat. En manada todo pesa menos."] = "Se uma missão ficar difícil, peça ajuda no chat. Em matilha tudo pesa menos.",
	["Si una subasta no se vende, pierdes el depósito: no pongas precios fuera de la realidad."] = "Se um leilão não vender, você perde o depósito: não ponha preços fora da realidade.",
	["Si vendes todo al comerciante"] = "Se vender tudo ao mercador",
	["Si ves a otro lobo por ahí, salúdalo de mi parte."] = "Se você vir outro lobo por aí, mande um oi por mim.",
	["Si ves carpas de colores en Villadorada o en Mulgore, llegó la Feria de la Luna Negra: hay juegos, premios y cartas que se juntan en mazos."] = "Se você vir tendas coloridas em Vila d'Ouro ou em Mulgore, chegou a Feira de Negraluna: tem jogos, prêmios e cartas que se juntam em baralhos.",
	["Si viajas con un mago, pídele un portal a la capital: te ahorra mucho camino."] = "Se você viajar com um mago, peça um portal para a capital: economiza muito caminho.",
	["Siempre"] = "Sempre",
	["Siempre con cebo"] = "Sempre com isca",
	["Siempre: te ofrece la historia de cada misión y un dato de cada zona nueva. A veces: de las misiones que tomas sin leer, y no siempre. Solo si le pido: con clic derecho, «Cuéntame algo de aquí». Las historias se guardan igual."] = "Sempre: ela oferece a história de cada missão e uma curiosidade de cada zona nova. Às vezes: das missões que você pega sem ler, e nem sempre. Só se eu pedir: com clique direito, «Me conte algo deste lugar». As histórias são guardadas do mesmo jeito.",
	["Siete días de caza contigo. Esto ya es costumbre, y me encanta."] = "Sete dias de caçada com você. Isso já é costume, e eu adoro.",
	["Sigilo"] = "Furtividade",
	["Sigilo y emboscadas: tú eliges cuándo pelear y desapareces cuando quieres."] = "Furtividade e emboscadas: você escolhe quando lutar e some quando quiser.",
	["Siglos después de la División, los Altonato que no soltaban la magia arcana fueron desterrados. Cruzaron el mar y fundaron Quel'Thalas: son los altos elfos."] = "Séculos depois da Cisão, os Bem-nascidos que não largavam a magia arcana foram desterrados. Cruzaram o mar e fundaram Quel'Thalas: são os altos elfos.",
	["Siglos después, los orcos Faucedraco usaron el Alma de Demonio para tener presa a Alexstrasza y criar dragones de guerra para la Horda."] = "Séculos depois, os orcs Presa do Dragão usaram a Alma Demoníaca para manter Alexstrasza presa e criar dragões de guerra para a Horda.",
	["Sigue a tu lado, pero no habla hasta las %s."] = "Ela continua ao seu lado, mas não fala até as %s.",
