	["Sombra suave en rincones, pliegues y bajo los objetos: da volumen a todo."] = "Sombra suave em cantos, dobras e sob os objetos: dá volume a tudo.",
	["Sombras"] = "Sombras",
	["Sombras con bordes más finos. Usa más memoria de video."] = "Sombras com bordas mais finas. Usa mais memória de vídeo.",
	["Sombras suaves"] = "Sombras suaves",
	["Son %s más que venderlo todo al comerciante."] = "São %s a mais do que vender tudo ao mercador.",
	["Son puntos de tu cuenta: los ganas con los retos del Legado (logros de Forever) en cualquier personaje, y cada personaje los gasta por su cuenta en sus árboles."] = "São pontos da sua conta: você os ganha com os desafios do Legado (conquistas do Forever) em qualquer personagem, e cada personagem os gasta por conta própria nas suas árvores.",
	["Son tres enanos que pelean juntos: uno dispara de lejos, otro es muy veloz y otro se protege con escudo. Mátenlos uno por uno."] = "São três anões que lutam juntos: um atira de longe, outro é muito rápido e outro se protege com escudo. Matem um de cada vez.",
