	["Sorpresa"] = "Surpresa",
	["Sorpresas y cofres"] = "Surpresas e baús",
	["Soy Lya, la loba de confianza del Alfa. Te acompaño, te cuento el lore de cada lugar y te ayudo con todo lo de Alfa. Y me encantan las salchichas."] = "Sou a Lya, a loba de confiança do Alfa. Acompanho você, conto o lore de cada lugar e ajudo com tudo do Alfa. E adoro salsichas.",
	["Stromgarde, la heredera de Strom, resiste a medias: trols, ogros y el Sindicato se pelean por sus ruinas."] = "Stromgarde, a herdeira de Strom, resiste a duras penas: trolls, ogros e o Sindicato brigam por suas ruínas.",
	["Su arpón envenena: quita el veneno si puedes."] = "O arpão dele envenena: remova o veneno se puder.",
	["Su botín está por descubrir"] = "O saque dele ainda está por descobrir",
