	["Ubicación de %s"] = "Localização de %s",
	["Ultra"] = "Ultra",
	["Un arma en cada mano y mucha ira: el que más daño hace en grupo."] = "Uma arma em cada mão e muita raiva: o que mais causa dano em grupo.",
	["Un arma grande de dos manos y golpes que hacen sangrar. La forma más fácil de subir."] = "Uma arma grande de duas mãos e golpes que fazem sangrar. O jeito mais fácil de subir de nível.",
	["Un aturdimiento cuando lo necesites."] = "Um atordoamento quando você precisar.",
	["Un aullido corto cada vez que entregas una misión. Viene apagado."] = "Um uivo curto toda vez que você entrega uma missão. Vem desligado.",
	["Un aullido de lobo, del propio juego, la primera vez que abres Alfa en cada sesión."] = "Um uivo de lobo, do próprio jogo, na primeira vez que você abre o Alfa em cada sessão.",
	["Un aviso con sus jefes y lo que llevas vencido, con un clic a sus consejos."] = "Um aviso com os chefes e quantos você já derrotou, a um clique das dicas.",
	["Un aviso corto con el lugar, su zona y el tiempo de camino."] = "Um aviso curto com o lugar, a zona e o tempo de caminho.",
	["Un aviso corto cuando se activa una habilidad que depende de lo que pasó, como Abrumar después de que el enemigo esquive."] = "Um aviso curto quando é ativada uma habilidade que depende do que aconteceu, como Sobrepujar depois que o inimigo se esquiva.",
	["Un aviso cuando vences a un jefe nuevo, con un clic a su botín."] = "Um aviso quando você derrota um chefe novo, a um clique do saque dele.",
	["Un aviso y una franja en tus bolsas con qué vender, qué conservar y a qué comerciante ir, con un clic para marcar la chatarra."] = "Um aviso e uma faixa nas suas bolsas com o que vender, o que guardar e a qual mercador ir, com um clique para marcar o lixo.",
	["Un barrido oscuro y suave sobre los íconos mientras su recarga corre."] = "Uma varredura escura e suave sobre os ícones enquanto a recarga corre.",
	["Un borde del color de la calidad: verde, azul, morado..."] = "Uma borda da cor da qualidade: verde, azul, roxo...",
	["Un borde verde que late sobre el botón de tu barra con la habilidad sugerida, para encontrarlo rápido."] = "Uma borda verde pulsante sobre o botão da sua barra com a habilidade sugerida, para achá-lo rápido.",
	["Un brujo con dos compañeros puede invocar al resto del grupo a la entrada de una mazmorra."] = "Um bruxo com dois ajudantes pode invocar o resto do grupo na entrada de uma masmorra.",
