	["Un cuadro pequeño y movible con tu vida y las estadísticas que más pesan para tu clase. En combate el juego oculta algunos números: se queda el último que se pudo leer."] = "Um quadro pequeno e móvel com sua vida e os atributos que mais pesam para sua classe. Em combate, o jogo esconde alguns números: fica o último que deu para ler.",
	["Un enemigo"] = "Um inimigo",
	["Un error, una mejora o un comentario, directo al desarrollador"] = "Um erro, uma melhoria ou um comentário, direto para o desenvolvedor",
	["Un fondo del color de tu clase bajo tu nombre."] = "Um fundo da cor da sua classe embaixo do seu nome.",
	["Un golpe enorme con el escudo y muchísima amenaza."] = "Um golpe enorme com o escudo e muitíssima ameaça.",
	["Un golpe más para gastar ira."] = "Mais um golpe para gastar raiva.",
	["Un golpe nuevo y fuerte para tu barra."] = "Um golpe novo e forte para a sua barra.",
	["Un gran aumento de daño para monstruos difíciles; además te libra del miedo."] = "Um grande aumento de dano para monstros difíceis; além disso, livra você do medo.",
	["Un grano fino de cine sobre el mundo."] = "Um granulado fino de cinema sobre o mundo.",
	["Un grano fino, como de cine. Casi no cuesta: se mueve unas 14 veces por segundo y solo mientras se ve."] = "Um granulado fino, como de cinema. Quase não custa nada: muda umas 14 vezes por segundo e só enquanto aparece.",
	["Un hechizo de tus barras tiene un rango viejo"] = "Um feitiço das suas barras está num grau antigo",
