	["Un mapa impecable"] = "Um mapa impecável",
	["Un marco dorado en lo que sirve para una misión (con «!» si empieza una)."] = "Uma moldura dourada no que serve para uma missão (com “!” se ele inicia uma).",
	["Un objeto que quieres: Alfa arma el camino para conseguirlo, con lo que haga falta antes."] = "Um item que você quer: o Alfa monta o caminho para consegui-lo, com o que for preciso antes.",
	["Un paisaje más bonito"] = "Uma paisagem mais bonita",
	["Un pescadito asado no me caería nada mal."] = "Um peixinho assado não cairia nada mal.",
