	["Un pin pequeño con su número donde te llevan los próximos pasos."] = "Um pequeno marcador numerado onde os próximos passos vão levar você.",
	["Un poco de golpe crítico, de esquivar y de armadura."] = "Um pouco de acerto crítico, esquiva e armadura.",
	["Un poco de vida de vuelta después de críticos."] = "Um pouco de vida de volta depois de críticos.",
	["Un poco más de defensa."] = "Um pouco mais de defesa.",
