	["Un punto para abrir la siguiente fila y fallar un poco menos."] = "Um ponto para abrir a próxima fileira e errar um pouco menos.",
	["Un raro vuelve más o menos entre media hora y una hora después de caer. Aquí ves hace cuánto lo cazaron tú o la manada."] = "Um raro volta mais ou menos entre meia hora e uma hora depois de cair. Aqui você vê há quanto tempo você ou a matilha o abateram.",
	["Un raro: %s"] = "Um raro: %s",
	["Un servicio cercano, un marcador de tu mapa, donde estás ahora o la entrada de una mazmorra."] = "Um serviço próximo, um marcador do seu mapa, onde você está agora ou a entrada de uma masmorra.",
	["Un signo de exclamación sobre quien te da misiones de tu nivel."] = "Um ponto de exclamação sobre quem dá missões do seu nível.",
	["Un signo de interrogación sobre quien recibe una misión ya lista."] = "Um ponto de interrogação sobre quem recebe uma missão já concluída.",
	["Un solo addon con todo lo que usas al jugar: guías paso a paso con flecha y ruta, mapa, bolsas, builds, curación con clic, recolección, mazmorras, pesca y comercio. Todo con el mismo estilo."] = "Um único addon com tudo o que você usa ao jogar: guias passo a passo com seta e rota, mapa, bolsas, builds, cura com clique, coleta, masmorras, pesca e comércio. Tudo no mesmo estilo.",
	["Un tanque que pega fuerte: mucha amenaza para grupos que hacen mucho daño, a cambio de menos defensa extra. Para tanques con algo de experiencia."] = "Um tanque que bate forte: muita ameaça para grupos que causam muito dano, em troca de menos defesa extra. Para tanques com alguma experiência.",
	["Un tramo más en la ruta que armas en la página Ruta: Alfa elige el camino para conseguirlo."] = "Mais um trecho na rota que você monta na página Rota: o Alfa escolhe o caminho para conseguir.",
	["Un «?» en cada página de Alfa para que Lya te la explique, y su propia tecla."] = "Um “?” em cada página do Alfa para a Lya explicar, e a tecla dela.",
	["Un ícono con la habilidad que conviene ahora. Solo muestra: nunca aprieta nada por ti."] = "Um ícone com a habilidade que convém agora. Só mostra: nunca aperta nada por você.",
	["Un ícono de misión en la placa de nombre de los enemigos y personajes que todavía necesitas para una misión de tu registro. En mazmorras el juego oculta esos datos y no se marcan."] = "Um ícone de missão na placa de nome dos inimigos e personagens que você ainda precisa para uma missão do seu registro. Em masmorras o jogo esconde esses dados e eles não são marcados.",
	["Una acción recomendada en grande y tu camino en un par de clics."] = "Uma ação recomendada em destaque e seu caminho em poucos cliques.",
	["Una barra bajo el buzón para tomar el dinero y los objetos de tus cartas con un clic, y lo que recibiste al final."] = "Uma barra sob a caixa de correio para pegar o dinheiro e os itens das suas cartas com um clique, e o que você recebeu no final.",
	["Una barra con los ataques que el jefe va a hacer y cuánto falta para cada uno. Así sabes cuándo moverte o defenderte."] = "Uma barra com os ataques que o chefe vai fazer e quanto falta para cada um. Assim você sabe quando se mover ou se defender.",
	["Una bienvenida nueva en 9 pasos con la intro del lobo: eliges el idioma de Alfa (hay 10) y cada cosa que hace sola por ti."] = "Boas-vindas novas em 9 passos com a intro do lobo: você escolhe o idioma do Alfa (são 10) e cada coisa que ele faz sozinho por você.",
	["Una cadena de texto lleva un build completo: la copias, la pasas y la pegan."] = "Um texto leva uma build completa: você copia, passa adiante e eles colam.",
	["Una cantidad de oro; se cumple cuando la llevas encima."] = "Uma quantidade de ouro; fica cumprida quando você a carrega.",
	["Una carta con objetos vence pronto"] = "Uma carta com itens expira em breve",
	["Una categoría…"] = "Uma categoria…",
	["Una cuenta de prueba no puede compartir"] = "Uma conta de teste não pode compartilhar",
	["Una fila con vuelo, posada, reparar, banco, buzón y tu entrenador, a un clic."] = "Uma fileira com voo, estalagem, reparo, banco, correio e seu instrutor, a um clique.",
	["Una flecha en pantalla que apunta a tu siguiente objetivo, con la distancia. Apagada: tú decides por dónde ir."] = "Uma seta na tela que aponta para o seu próximo objetivo, com a distância. Desligada: você decide por onde ir.",
	["Una flecha verde en cada objeto de tus bolsas que es una mejora para tu especialización."] = "Uma seta verde em cada item das suas bolsas que é uma melhoria para a sua especialização.",
	["Una flecha verde en el equipo que es mejor que lo que llevas puesto, según tu clase y nivel."] = "Uma seta verde no equipamento melhor do que o que você está usando, de acordo com sua classe e nível.",
	["Una franja verde clara muestra las curas que ya vienen en camino."] = "Uma faixa verde-clara mostra as curas que já estão a caminho.",
	["Una guía para tu nivel y tu zona, o tu propia ruta de misiones."] = "Um guia para o seu nível e sua zona, ou sua própria rota de missões.",
	["Una hora de caza"] = "Uma hora de caçada",
	["Una hora de caza, aviso de cadena, «Deshacer» al omitir y cuánto te falta de tu guía."] = "Uma hora de caçada, aviso de corrente, “Desfazer” ao pular e quanto falta do seu guia.",
	["Una huella sobre la mejor para tu clase (o la que más vale al venderla) y «Alfa te recomienda». Nunca elige por ti."] = "Uma pegada na melhor para sua classe (ou na que vale mais para vender) e \"O Alfa recomenda\". Nunca escolhe por você.",
	["Una loba gordita como yo necesita sus tres comidas... y sus botanas."] = "Uma loba gordinha como eu precisa das suas três refeições... e dos seus petiscos.",
	["Una loba negra que te da consejos y ánimo en el camino, sin estorbar. En memoria de una gran perrita."] = "Uma loba negra que dá dicas e ânimo pelo caminho, sem atrapalhar. Em memória de uma cachorrinha incrível.",
	["Una loba que cuida tan bien a su lobo merece una salchicha, ¿no crees?"] = "Uma loba que cuida tão bem do seu lobo merece uma salsicha, não acha?",
	["Una línea con el enlace de la misión cuando completas sus objetivos, otra cuando está lista para entregar y otra al entregarla. En grupo la ve todo el grupo, con o sin Alfa; solo, sale en tu chat. Nunca en banda."] = "Uma linha com o link da missão quando você completa os objetivos, outra quando está pronta para entregar e outra ao entregá-la. Em grupo, todo o grupo vê, com ou sem Alfa; sozinho, aparece no seu chat. Nunca em raide.",
	["Una línea corta debajo del ícono, como «Golpe mortal: recarga lista». Cada una sale hasta 4 veces y luego se calla; su × la calla antes."] = "Uma linha curta embaixo do ícone, como «Golpe Mortal: recarga pronta». Cada uma aparece até 4 vezes e depois se cala; o × dela a cala antes.",
	["Una línea debajo del aviso con lo que pasó."] = "Uma linha embaixo do aviso com o que aconteceu.",
	["Una línea roja arriba avisa cuando un enemigo va por ese compañero."] = "Uma linha vermelha em cima avisa quando um inimigo vai atrás desse companheiro.",
	["Una mano"] = "Uma Mão",
	["Una meta que marcas tú (el botón de hecha del rastreador o de esta lista)."] = "Uma meta que você marca (o botão de feita do rastreador ou desta lista).",
	["Una misión"] = "Uma missão",
	["Una moneda sobre lo gris y lo que marcaste como chatarra."] = "Uma moeda sobre o cinza e o que você marcou como lixo.",
	["Una nota con el instructor más cercano cuando tienes habilidades nuevas."] = "Uma nota com o instrutor mais próximo quando você tem habilidades novas.",
	["Una revisión completa de todos los módulos: más de 60 arreglos."] = "Uma revisão completa de todos os módulos: mais de 60 correções.",
	["Una revisión completa para la versión estable: más de 20 arreglos en mazmorras con grupo, combate, el mapa, Pesca, Talentos y más."] = "Uma revisão completa para a versão estável: mais de 20 correções em masmorras em grupo, combate, mapa, Pesca, Talentos e mais.",
	["Una ruta es tu árbol de tramos: misiones de XP, de oro, de clase, materiales u objetos. Elige una de estas para empezar:"] = "Uma rota é sua árvore de trechos: missões de XP, de ouro, de classe, materiais ou itens. Escolha uma destas para começar:",
	["Una ruta necesita al menos 3 lugares que tu habilidad alcance. Elige otro tipo o recurso abajo, o recolecta aquí: Alfa anota cada nodo que encuentras."] = "Uma rota precisa de pelo menos 3 lugares que sua habilidade alcance. Escolha outro tipo ou recurso abaixo, ou colete aqui: o Alfa anota cada ponto que você encontra.",
